insert into help_articles (id, topic, title, summary, tags, popular, html, position, updated_on) values ($h$what-is-smb-hub$h$, $h$start$h$, $h$What is SME Hub?$h$, $h$A free community for Canadian small-business owners, from the team behind CanadianSME Small Business Magazine.$h$, $h$about community canadiansme$h$, true, $h$<p>SME Hub is an online community where Canadian small-business owners connect, ask questions, share what works and find customers through recommendations and warm introductions.</p><p>It is run by CanadianSME, the team behind CanadianSME Small Business Magazine, which has covered Canadian small business since 2018.</p><h3>What you can do on SME Hub</h3><ul><li>Build a profile for you and a page for your business.</li><li>Ask questions and share wins, jobs and introductions in the feed.</li><li>Join groups on topics like money, marketing, hiring, exporting and AI.</li><li>Find and message other owners, advisors and Canadian suppliers.</li><li>Get recommended by people you have worked with, and ask for introductions through people you both know.</li><li>List your business in the Canada-wide Business Directory.</li><li>Use AI to answer business questions and suggest who to meet.</li></ul><div class="call tip"><b>Tip</b><span>SME Hub is free to join. Paid plans add things like offers, private groups and more AI. See <a href="#/a/plans-compared">Free, Plus and Advisor plans compared</a>.</span></div><figure class="fig"><button type="button" class="zoom" data-zoom="media/start-hero.webp" aria-label="Enlarge screenshot: The SME Hub welcome page"><img src="media/start-hero.webp" alt="The SME Hub welcome page" loading="lazy"></button><figcaption>The SME Hub welcome page</figcaption></figure>$h$, 0, '2026-11-27') on conflict (id) do update set topic = excluded.topic, title = excluded.title, summary = excluded.summary, tags = excluded.tags, popular = excluded.popular, html = excluded.html, position = excluded.position, updated_on = excluded.updated_on;
insert into help_articles (id, topic, title, summary, tags, popular, html, position, updated_on) values ($h$create-account$h$, $h$start$h$, $h$Create your account$h$, $h$Join free in about two minutes. No card needed.$h$, $h$join sign up register new account password code$h$, true, $h$<figure class="fig vid"><div class="vbox"><video src="media/vid-signup.mp4" poster="media/vid-signup.jpg" muted loop playsinline preload="none" aria-label="Video walkthrough: Joining SME Hub, start to finish"></video><button type="button" class="vplay" aria-label="Play walkthrough">&#9654;</button></div><figcaption><span class="vtag">Walkthrough</span>Joining SME Hub, start to finish</figcaption></figure><ol class="steps"><li>Go to SME Hub and select <b>Join free</b> (or <b>Join now</b> at the top of any page).</li><li>Sign up with <b>Google</b> or <b>LinkedIn</b>, or fill in your first and last name, your business name and your work email. No business yet? Write "Starting soon".</li><li>Add your <b>business website or Google listing</b> if you have one. It’s optional, and it lets AI set up your profile for you.</li><li>Create a password. The checklist turns green as you meet each rule: 8 or more characters, at least one number, upper and lower case or a symbol, and not a common password.</li><li>Choose your province or territory and agree to the Terms. Ticking the newsletter box is up to you.</li><li>Select <b>Create my free account</b>.</li><li>We email you a <b>6-digit code</b>. Type or paste it and select <b>Confirm my email</b>. The code works for 60 minutes. Didn’t get it? Check your spam folder, or select <b>Send a new code</b>.</li><li>AI sets up your profile. If you added your website, it drafts your profile and business page from it. No website? Answer 3 quick questions instead. Check the draft, change anything you like, then select <b>Looks good, save</b>. See <a href="#/a/first-week">Get your profile ready</a>.</li></ol><figure class="fig"><button type="button" class="zoom" data-zoom="media/acct-signup.webp" aria-label="Enlarge screenshot: The Join page"><img src="media/acct-signup.webp" alt="The Join page" loading="lazy"></button><figcaption>The Join page</figcaption></figure><figure class="fig"><button type="button" class="zoom" data-zoom="media/acct-verify.webp" aria-label="Enlarge screenshot: Enter the 6-digit code from your email"><img src="media/acct-verify.webp" alt="Enter the 6-digit code from your email" loading="lazy"></button><figcaption>Enter the 6-digit code from your email</figcaption></figure><figure class="fig"><button type="button" class="zoom" data-zoom="media/start-ai-draft.webp" aria-label="Enlarge screenshot: AI drafts your profile and business page. Nothing is public until you save."><img src="media/start-ai-draft.webp" alt="AI drafts your profile and business page. Nothing is public until you save." loading="lazy"></button><figcaption>AI drafts your profile and business page. Nothing is public until you save.</figcaption></figure><div class="call note"><b>Good to know</b><span>Use your real name and your real business. Profiles that pretend to be someone else are removed. See <a href="#/a/community-guidelines">Community guidelines</a>.</span></div>$h$, 1, '2026-11-27') on conflict (id) do update set topic = excluded.topic, title = excluded.title, summary = excluded.summary, tags = excluded.tags, popular = excluded.popular, html = excluded.html, position = excluded.position, updated_on = excluded.updated_on;
insert into help_articles (id, topic, title, summary, tags, popular, html, position, updated_on) values ($h$first-week$h$, $h$start$h$, $h$Get your profile ready$h$, $h$Five quick things that help the right people find you, and how AI can do most of them for you.$h$, $h$onboarding checklist new member ready profile complete photo headline business page website ai setup$h$, true, $h$<p>Your profile is <b>ready</b> when it has all 5 of these:</p><ol class="steps"><li><b>A profile photo.</b> Owners reply to people they can see.</li><li><b>A headline.</b> Your role and business, for example "Owner, Morgan Home Renovations".</li><li><b>Your city.</b> So owners near you can find you. Only your city shows, never your address.</li><li><b>What you can help with.</b> Short tags. They decide who finds you in search.</li><li><b>A business page.</b> Puts your business in the Business Directory.</li></ol><p>Until your profile is ready, a <b>Your profile is N of 5 ready</b> card sits at the top of your Home page and your profile. Each step has its own button.</p><figure class="fig"><button type="button" class="zoom" data-zoom="media/start-ready.webp" aria-label="Enlarge screenshot: The “Your profile” card. Select a button to finish that step."><img src="media/start-ready.webp" alt="The “Your profile” card. Select a button to finish that step." loading="lazy"></button><figcaption>The “Your profile” card. Select a button to finish that step.</figcaption></figure><h3>Let AI do it for you</h3><p>Select <b>Set it up for me</b> on the card, then paste your business website or Google Business Profile link. AI reads it and drafts your headline, city, introduction, "Can help with" tags and business page. You check everything and change anything before you save.</p><p>No website? Select <b>No website? Answer 3 questions</b>: your role and business, your city, and what you can help with.</p><h3>What a ready profile gets you</h3><div class="tw"><table><thead><tr><th>Until your profile has…</th><th>You can’t…</th></tr></thead><tbody><tr><td>A photo and a headline</td><td>Send connection requests or ask for introductions. We ask you to add them first, in the same window.</td></tr><tr><td>A business page</td><td>Appear in the Business Directory</td></tr><tr><td>All 5</td><td>Appear in member search, daily "People to meet" and AI matchmaking for other members</td></tr></tbody></table></div><p>You can always read posts, join groups, ask questions and message people who contact you.</p><figure class="fig"><button type="button" class="zoom" data-zoom="media/network-photo-first.webp" aria-label="Enlarge screenshot: Add a photo and headline before your first connection request"><img src="media/network-photo-first.webp" alt="Add a photo and headline before your first connection request" loading="lazy"></button><figcaption>Add a photo and headline before your first connection request</figcaption></figure><div class="call tip"><b>Tip</b><span>A ready profile also lets you apply for the <a href="#/a/member-spotlight">Get featured: the Member Spotlight</a> in CanadianSME Small Business Magazine.</span></div><h3>Reminder emails</h3><p>If your profile isn’t ready, we send up to 3 short emails in your first 2 weeks, each about one missing step. They stop as soon as your profile is ready. You can turn them off in <b>Email notifications</b>.</p>$h$, 2, '2026-11-27') on conflict (id) do update set topic = excluded.topic, title = excluded.title, summary = excluded.summary, tags = excluded.tags, popular = excluded.popular, html = excluded.html, position = excluded.position, updated_on = excluded.updated_on;
insert into help_articles (id, topic, title, summary, tags, popular, html, position, updated_on) values ($h$find-your-way$h$, $h$start$h$, $h$Find your way around$h$, $h$The menus, the Explore menu and where everything lives.$h$, $h$menu navigation explore$h$, false, $h$<p>The menu at the top is the same on every page.</p><div class="tw"><table><thead><tr><th>Menu item</th><th>What it opens</th></tr></thead><tbody><tr><td>Home</td><td>Your feed, stories and shortcuts</td></tr><tr><td>Network</td><td>The member directory and map of Canada</td></tr><tr><td>Business Directory</td><td>Canadian businesses you can search and contact</td></tr><tr><td>About</td><td>About SME Hub, resources and provincial guides</td></tr><tr><td>Explore</td><td>Groups, members, hashtags, events, AI tools, member blogs, advisors, the Member Spotlight, the Pavilion, businesses for sale, courses, the blog, news and the podcast</td></tr><tr><td>Help</td><td>This Help Centre</td></tr><tr><td>Bell</td><td>Your notifications</td></tr><tr><td>Me</td><td>Your profile, account and settings</td></tr><tr><td>Upgrade plan</td><td>Membership plans</td></tr></tbody></table></div><p>Messages open in a small chat window in the bottom-right corner of every page. See <a href="#/a/messaging-basics">Send a message</a>.</p><figure class="fig"><button type="button" class="zoom" data-zoom="media/start-header.webp" aria-label="Enlarge screenshot: The menu at the top of every page"><img src="media/start-header.webp" alt="The menu at the top of every page" loading="lazy"></button><figcaption>The menu at the top of every page</figcaption></figure><figure class="fig"><button type="button" class="zoom" data-zoom="media/start-explore.webp" aria-label="Enlarge screenshot: The Explore menu"><img src="media/start-explore.webp" alt="The Explore menu" loading="lazy"></button><figcaption>The Explore menu</figcaption></figure>$h$, 3, '2026-11-27') on conflict (id) do update set topic = excluded.topic, title = excluded.title, summary = excluded.summary, tags = excluded.tags, popular = excluded.popular, html = excluded.html, position = excluded.position, updated_on = excluded.updated_on;
insert into help_articles (id, topic, title, summary, tags, popular, html, position, updated_on) values ($h$founding-member$h$, $h$start$h$, $h$The Founding Member badge$h$, $h$The first 500 members keep a permanent Founding Member badge.$h$, $h$badge early$h$, false, $h$<p>The first 500 members to join SME Hub get a red <b>Founding Member</b> badge on their profile. The badge stays on your profile for good, even if you change plans.</p><p>There is also a Founding Member offer for paid plans. See <a href="#/a/founding-offer">Founding Member offer</a>.</p><figure class="fig"><button type="button" class="zoom" data-zoom="media/profile-badges.webp" aria-label="Enlarge screenshot: The Founding Member badge on a profile"><img src="media/profile-badges.webp" alt="The Founding Member badge on a profile" loading="lazy"></button><figcaption>The Founding Member badge on a profile</figcaption></figure>$h$, 4, '2026-11-27') on conflict (id) do update set topic = excluded.topic, title = excluded.title, summary = excluded.summary, tags = excluded.tags, popular = excluded.popular, html = excluded.html, position = excluded.position, updated_on = excluded.updated_on;
insert into help_articles (id, topic, title, summary, tags, popular, html, position, updated_on) values ($h$visitor-vs-member$h$, $h$start$h$, $h$What visitors can see$h$, $h$What people who have not joined can and cannot see.$h$, $h$public logged out guest$h$, false, $h$<p>People who have not joined can read the public parts of SME Hub: the welcome page, membership plans, CanadianSME articles, resource centres, the Business Directory and public business pages.</p><p>To post, comment, react, connect, message, join a group or see members-only stories, they need to join. Any of those actions opens the <b>Join</b> window.</p><div class="call note"><b>Good to know</b><span>Your profile settings decide which parts of your profile visitors can see. See <a href="#/a/profile-privacy">Choose who sees each part of your profile</a>.</span></div>$h$, 5, '2026-11-27') on conflict (id) do update set topic = excluded.topic, title = excluded.title, summary = excluded.summary, tags = excluded.tags, popular = excluded.popular, html = excluded.html, position = excluded.position, updated_on = excluded.updated_on;
insert into help_articles (id, topic, title, summary, tags, popular, html, position, updated_on) values ($h$edit-profile$h$, $h$profile$h$, $h$Edit your profile$h$, $h$Change your name, headline, city, introduction and the details members see.$h$, $h$edit headline about$h$, true, $h$<figure class="fig"><button type="button" class="zoom" data-zoom="media/profile-hero.webp" aria-label="Enlarge screenshot: Select Edit profile on your own profile"><img src="media/profile-hero.webp" alt="Select Edit profile on your own profile" loading="lazy"></button><figcaption>Select Edit profile on your own profile</figcaption></figure><ol class="steps"><li>Select <b>Me</b>, then your name, to open your profile.</li><li>Select <b>Edit profile</b>.</li><li>Update your name, headline (your role and business), city, introduction and links.</li><li>Select <b>Save</b>.</li></ol><h3>What to include</h3><ul><li><b>Headline:</b> your role and business, for example "Owner, Morgan Home Renovations".</li><li><b>Introduction:</b> two or three sentences about who you serve and how. Let AI write a first draft: see <a href="#/a/ai-profile-builder">Write your profile with AI</a>.</li><li><b>Can help with</b> and <b>Looking for:</b> short tags. These power suggestions and matchmaking.</li><li><b>Availability:</b> when you are usually free to meet, for example weekday mornings.</li><li><b>Social links:</b> LinkedIn, Facebook, Instagram, X, YouTube and others.</li></ul><figure class="fig"><button type="button" class="zoom" data-zoom="media/profile-edit.webp" aria-label="Enlarge screenshot: The Edit your profile window"><img src="media/profile-edit.webp" alt="The Edit your profile window" loading="lazy"></button><figcaption>The Edit your profile window</figcaption></figure>$h$, 6, '2026-11-27') on conflict (id) do update set topic = excluded.topic, title = excluded.title, summary = excluded.summary, tags = excluded.tags, popular = excluded.popular, html = excluded.html, position = excluded.position, updated_on = excluded.updated_on;
insert into help_articles (id, topic, title, summary, tags, popular, html, position, updated_on) values ($h$photo-and-header$h$, $h$profile$h$, $h$Change your header image$h$, $h$Change your header on any plan, and the best image sizes.$h$, $h$image cover banner picture size$h$, false, $h$<p>Every member can change their header, on any plan.</p><h3>Change your header</h3><ol class="steps"><li>Open your profile and select <b>Edit header</b> in the top-right corner of the header. You can also select <b>Edit profile</b>, then <b>Change</b> next to Header image.</li><li>Choose <b>Use a photo</b> and pick one from your computer or phone, or choose <b>Use a colour</b>.</li><li>For a photo, drag it or use the sliders to zoom and choose the part to show.</li><li>Select <b>Save header</b>.</li></ol><figure class="fig"><button type="button" class="zoom" data-zoom="media/header-editor.webp" aria-label="Enlarge screenshot: Editing your header"><img src="media/header-editor.webp" alt="Editing your header" loading="lazy"></button><figcaption>Editing your header</figcaption></figure><p>Changed your mind? Open the editor and select <b>Go back to the original header</b>.</p><h3>Image sizes</h3><div class="tw"><table><thead><tr><th>Image</th><th>Best size</th><th>How it shows</th></tr></thead><tbody><tr><td>Profile photo</td><td>At least 400 × 400 pixels, square</td><td>In a circle, from small icons up to the large photo on your profile</td></tr><tr><td>Profile header</td><td>1584 × 396 pixels (4 to 1)</td><td>Across the top of your profile. The edges are trimmed on phones, so keep text and faces near the middle</td></tr></tbody></table></div><p>Use JPG, PNG or WebP, up to 8 MB. If you do not add a header, SME Hub shows a default illustration.</p><div class="call tip"><b>Tip</b><span>Pick a header that shows your work, for example your shop, your product or your team at work.</span></div><figure class="fig"><button type="button" class="zoom" data-zoom="media/profile-header.webp" aria-label="Enlarge screenshot: A profile with a header image and photo"><img src="media/profile-header.webp" alt="A profile with a header image and photo" loading="lazy"></button><figcaption>A profile with a header image and photo</figcaption></figure>$h$, 7, '2026-11-27') on conflict (id) do update set topic = excluded.topic, title = excluded.title, summary = excluded.summary, tags = excluded.tags, popular = excluded.popular, html = excluded.html, position = excluded.position, updated_on = excluded.updated_on;
insert into help_articles (id, topic, title, summary, tags, popular, html, position, updated_on) values ($h$profile-types$h$, $h$profile$h$, $h$Profile types and badges$h$, $h$Business owner, SME Advisor, maker, service provider: what each label means.$h$, $h$type badge advisor maker$h$, false, $h$<p>Your profile type tells members what kind of member you are. It shows as a tag on your profile and member card, and it helps people filter the directory.</p><ul><li><b>Business owner:</b> you run a small business.</li><li><b>SME Advisor:</b> an expert who serves small businesses, such as an accountant, lawyer, consultant or coach. Comes with the Advisor plan. See <a href="#/a/become-advisor">Become an SME Advisor</a>.</li><li><b>Maker:</b> you make products in Canada.</li><li><b>Service provider:</b> a company that sells services or software to small businesses.</li></ul><h3>Badges</h3><ul><li><b>Founding Member:</b> one of the first 500 members. See <a href="#/a/founding-member">The Founding Member badge</a>.</li><li><b>SME Advisor:</b> shown on your profile and your posts.</li><li><b>Recommended by N:</b> how many members have recommended you. See <a href="#/a/recommendations">Recommendations: give and ask</a>.</li></ul><figure class="fig"><button type="button" class="zoom" data-zoom="media/profile-badges.webp" aria-label="Enlarge screenshot: Badges and labels under a member’s name"><img src="media/profile-badges.webp" alt="Badges and labels under a member’s name" loading="lazy"></button><figcaption>Badges and labels under a member’s name</figcaption></figure>$h$, 8, '2026-11-27') on conflict (id) do update set topic = excluded.topic, title = excluded.title, summary = excluded.summary, tags = excluded.tags, popular = excluded.popular, html = excluded.html, position = excluded.position, updated_on = excluded.updated_on;
insert into help_articles (id, topic, title, summary, tags, popular, html, position, updated_on) values ($h$recommendations$h$, $h$profile$h$, $h$Recommendations: give and ask$h$, $h$Vouch for people you have worked with, and ask clients and partners to vouch for you.$h$, $h$referral vouch testimonial approve$h$, true, $h$<p>Recommendations are short notes from members you have worked with. They show on your profile, and your profile header shows <b>Recommended by N</b>.</p><h3>Write a recommendation</h3><figure class="fig vid"><div class="vbox"><video src="media/vid-recommend.mp4" poster="media/vid-recommend.jpg" muted loop playsinline preload="none" aria-label="Video walkthrough: Writing a recommendation for another member"></video><button type="button" class="vplay" aria-label="Play walkthrough">&#9654;</button></div><figcaption><span class="vtag">Walkthrough</span>Writing a recommendation for another member</figcaption></figure><ol class="steps"><li>Open the member’s profile.</li><li>Select <b>Recommend</b> followed by their name.</li><li>Choose how you know them, for example <b>Client</b> or <b>Referral partner</b>.</li><li>Write one or two honest sentences about working with them.</li><li>Select <b>Send for approval</b>. It appears on their profile once they approve it.</li></ol><h3>Approve recommendations you receive</h3><p>New recommendations wait in your <b>Recommendations</b> section under <b>Waiting for your approval</b>. Select <b>Show on my profile</b> or <b>Do not show</b>.</p><h3>Ask for a recommendation</h3><ol class="steps"><li>Open your own profile and go to <b>Recommendations</b>.</li><li>Select <b>Ask for a recommendation</b>.</li><li>Choose the people to ask, add a short note and select <b>Send</b>.</li></ol><div class="call tip"><b>Tip</b><span>Specific beats general: "Rebuilt our office in three weeks and stayed on budget" helps more than "Great to work with".</span></div><figure class="fig"><button type="button" class="zoom" data-zoom="media/profile-recs.webp" aria-label="Enlarge screenshot: Recommendations on your profile, including ones waiting for your approval"><img src="media/profile-recs.webp" alt="Recommendations on your profile, including ones waiting for your approval" loading="lazy"></button><figcaption>Recommendations on your profile, including ones waiting for your approval</figcaption></figure>$h$, 9, '2026-11-27') on conflict (id) do update set topic = excluded.topic, title = excluded.title, summary = excluded.summary, tags = excluded.tags, popular = excluded.popular, html = excluded.html, position = excluded.position, updated_on = excluded.updated_on;
insert into help_articles (id, topic, title, summary, tags, popular, html, position, updated_on) values ($h$who-viewed$h$, $h$profile$h$, $h$Who viewed my profile$h$, $h$See who looked at your profile in the last 30 days.$h$, $h$views viewers analytics private browsing$h$, true, $h$<p>Your profile shows a <b>Profile viewers</b> card, visible only to you. It lists members who viewed your profile recently and shows a 30-day chart.</p><div class="call plan"><b>Plans</b><span>Free members see the 2 most recent viewers. Plus and Advisor members see everyone.</span></div><h3>Browse privately</h3><p>If you don’t want members to know you viewed them:</p><ol class="steps"><li>Go to <b>Me</b>, then <b>Privacy and account</b>.</li><li>Select <b>Profile privacy</b>, then under <b>Activity</b> turn off <b>Record profile views</b>.</li></ol><div class="call note"><b>Good to know</b><span>When you browse privately, you also can’t see who viewed you. Visitors who are not signed in are never shown.</span></div><figure class="fig"><button type="button" class="zoom" data-zoom="media/profile-viewers.webp" aria-label="Enlarge screenshot: The profile viewers chart and list. Only you can see it"><img src="media/profile-viewers.webp" alt="The profile viewers chart and list. Only you can see it" loading="lazy"></button><figcaption>The profile viewers chart and list. Only you can see it</figcaption></figure>$h$, 10, '2026-11-27') on conflict (id) do update set topic = excluded.topic, title = excluded.title, summary = excluded.summary, tags = excluded.tags, popular = excluded.popular, html = excluded.html, position = excluded.position, updated_on = excluded.updated_on;
insert into help_articles (id, topic, title, summary, tags, popular, html, position, updated_on) values ($h$profile-privacy$h$, $h$profile$h$, $h$Choose who sees each part of your profile$h$, $h$Set each part of your profile to Public, All members, My connections or Only me.$h$, $h$privacy visibility$h$, false, $h$<ol class="steps"><li>Go to <b>Me</b>, then <b>Privacy and account</b>.</li><li>Select <b>Profile privacy</b>. Pick <b>Open</b>, <b>Balanced</b> or <b>Private</b> to set everything at once, or choose a setting for each part.</li></ol><div class="tw"><table><thead><tr><th>Setting</th><th>Who can see it</th></tr></thead><tbody><tr><td>Public</td><td>Anyone, including people who have not joined</td></tr><tr><td>All members</td><td>Signed-in SME Hub members</td></tr><tr><td>My connections</td><td>Only members you are connected with</td></tr><tr><td>Only me</td><td>Only you</td></tr></tbody></table></div><figure class="fig"><button type="button" class="zoom" data-zoom="media/account-privacy.webp" aria-label="Enlarge screenshot: Choose who can see each part of your profile"><img src="media/account-privacy.webp" alt="Choose who can see each part of your profile" loading="lazy"></button><figcaption>Choose who can see each part of your profile</figcaption></figure>$h$, 11, '2026-11-27') on conflict (id) do update set topic = excluded.topic, title = excluded.title, summary = excluded.summary, tags = excluded.tags, popular = excluded.popular, html = excluded.html, position = excluded.position, updated_on = excluded.updated_on;
insert into help_articles (id, topic, title, summary, tags, popular, html, position, updated_on) values ($h$member-spotlight$h$, $h$profile$h$, $h$Get featured: the Member Spotlight$h$, $h$Apply to be featured in CanadianSME Small Business Magazine.$h$, $h$spotlight featured magazine press feature canadiansme$h$, false, $h$<p>Every month, CanadianSME Small Business Magazine and its newsletter feature SME Hub members and their businesses. It’s free.</p><h3>Who can apply</h3><p>Any member whose profile is ready: photo, headline, city, "Can help with" and a business page. See <a href="#/a/first-week">Get your profile ready</a>.</p><h3>How to apply</h3><ol class="steps"><li>Open <b>Explore</b>, then <b>Member Spotlight</b>. Once your profile is ready, you’ll also see an <b>Apply</b> button at the top of your profile.</li><li>Answer 3 short questions: what your business does, one win or lesson, and what you’d like readers to know.</li><li>Tick the box so CanadianSME can use your photo, business name and answers.</li><li>Select <b>Apply for the Spotlight</b>.</li></ol><figure class="fig"><button type="button" class="zoom" data-zoom="media/profile-spotlight.webp" aria-label="Enlarge screenshot: Applying for the Member Spotlight"><img src="media/profile-spotlight.webp" alt="Applying for the Member Spotlight" loading="lazy"></button><figcaption>Applying for the Member Spotlight</figcaption></figure><h3>What happens next</h3><p>The CanadianSME editorial team picks members each month. If you’re chosen, we email you with the issue, your editor and what they need. Chosen members get a feature in the magazine, a mention in the newsletter, a social media post and a Spotlight badge on their profile for 30 days.</p>$h$, 12, '2026-11-27') on conflict (id) do update set topic = excluded.topic, title = excluded.title, summary = excluded.summary, tags = excluded.tags, popular = excluded.popular, html = excluded.html, position = excluded.position, updated_on = excluded.updated_on;
insert into help_articles (id, topic, title, summary, tags, popular, html, position, updated_on) values ($h$connect-vs-follow$h$, $h$network$h$, $h$Connect or follow: what is the difference?$h$, $h$Connections are two-way. Following is one-way.$h$, $h$connection follow request$h$, true, $h$<ul><li><b>Connect:</b> you send a request and the other member accepts. You both see each other’s updates, you can share with "Connections only", and you can introduce each other to people.</li><li><b>Follow:</b> you see someone’s public posts in your feed. They don’t need to accept.</li></ul><p>When you connect with someone, you also follow them automatically.</p><div class="call note"><b>Good to know</b><span>You need a profile photo and a headline before you can send connection requests. If either is missing, SME Hub asks you to add them first, in the same window. See <a href="#/a/first-week">Get your profile ready</a>.</span></div><h3>Send a connection request</h3><ol class="steps"><li>Select <b>+ Connect</b> on a member’s profile, card or post.</li><li>The button changes to <b>Request sent</b> until they reply.</li></ol><figure class="fig"><button type="button" class="zoom" data-zoom="media/network-actions.webp" aria-label="Enlarge screenshot: Connect, Message and Follow on a member’s profile"><img src="media/network-actions.webp" alt="Connect, Message and Follow on a member’s profile" loading="lazy"></button><figcaption>Connect, Message and Follow on a member’s profile</figcaption></figure>$h$, 13, '2026-11-27') on conflict (id) do update set topic = excluded.topic, title = excluded.title, summary = excluded.summary, tags = excluded.tags, popular = excluded.popular, html = excluded.html, position = excluded.position, updated_on = excluded.updated_on;
insert into help_articles (id, topic, title, summary, tags, popular, html, position, updated_on) values ($h$member-directory$h$, $h$network$h$, $h$Find members in the Network directory$h$, $h$Search by name, industry or city, filter by province and see members on a map.$h$, $h$search directory map members$h$, false, $h$<ol class="steps"><li>Select <b>Network</b> in the top menu.</li><li>Search by name, business or what someone can help with.</li><li>Use the filters to narrow by profile type, province, city or industry.</li><li>Switch to the <b>map</b> to see members across Canada.</li></ol><p>Each card shows the member’s photo, role, city, profile type and mutual connections, with a button to connect.</p><figure class="fig"><button type="button" class="zoom" data-zoom="media/network-directory.webp" aria-label="Enlarge screenshot: The Network directory with the map of Canada"><img src="media/network-directory.webp" alt="The Network directory with the map of Canada" loading="lazy"></button><figcaption>The Network directory with the map of Canada</figcaption></figure>$h$, 14, '2026-11-27') on conflict (id) do update set topic = excluded.topic, title = excluded.title, summary = excluded.summary, tags = excluded.tags, popular = excluded.popular, html = excluded.html, position = excluded.position, updated_on = excluded.updated_on;
insert into help_articles (id, topic, title, summary, tags, popular, html, position, updated_on) values ($h$warm-introductions$h$, $h$network$h$, $h$Ask for a warm introduction$h$, $h$Meet someone through a connection you both share.$h$, $h$intro introduction referral$h$, true, $h$<p>A warm introduction is when someone you both know introduces you. It is the fastest way to get a reply.</p><figure class="fig vid"><div class="vbox"><video src="media/vid-connect.mp4" poster="media/vid-connect.jpg" muted loop playsinline preload="none" aria-label="Video walkthrough: Connecting with a member, then asking a mutual connection for an introduction"></video><button type="button" class="vplay" aria-label="Play walkthrough">&#9654;</button></div><figcaption><span class="vtag">Walkthrough</span>Connecting with a member, then asking a mutual connection for an introduction</figcaption></figure><ol class="steps"><li>Open the profile of the person you want to meet.</li><li>Look for <b>mutual connections</b>.</li><li>Select <b>Ask for an introduction</b>.</li><li>Under <b>Who should introduce you?</b>, choose the mutual connection to ask.</li><li>Write a short note saying why you want to meet, then select <b>Send request</b>.</li><li>Your connection decides whether to make the introduction. You’ll get a message either way.</li></ol><div class="call tip"><b>Tip</b><span>Explain what’s in it for the other person, for example "I’m looking for a bakery to supply our café events".</span></div><figure class="fig"><button type="button" class="zoom" data-zoom="media/network-intro.webp" aria-label="Enlarge screenshot: The Ask for an introduction window"><img src="media/network-intro.webp" alt="The Ask for an introduction window" loading="lazy"></button><figcaption>The Ask for an introduction window</figcaption></figure>$h$, 15, '2026-11-27') on conflict (id) do update set topic = excluded.topic, title = excluded.title, summary = excluded.summary, tags = excluded.tags, popular = excluded.popular, html = excluded.html, position = excluded.position, updated_on = excluded.updated_on;
insert into help_articles (id, topic, title, summary, tags, popular, html, position, updated_on) values ($h$people-to-meet$h$, $h$network$h$, $h$Daily people to meet$h$, $h$Suggestions based on what you need and what others offer.$h$, $h$suggestions recommendations daily$h$, false, $h$<p>Every day SME Hub suggests members you may want to meet. Suggestions use your <b>Looking for</b> and <b>Can help with</b> tags, your city and your groups.</p><div class="call plan"><b>Plans</b><span>Free members get 3 suggestions a day. Plus and Advisor members are shown more often in other members’ suggestions.</span></div><p>For a deeper search, use AI matchmaking: see <a href="#/a/ai-matchmaking">AI matchmaking: meet the right owner</a>.</p><figure class="fig"><button type="button" class="zoom" data-zoom="media/network-meet.webp" aria-label="Enlarge screenshot: Daily suggestions of people worth meeting"><img src="media/network-meet.webp" alt="Daily suggestions of people worth meeting" loading="lazy"></button><figcaption>Daily suggestions of people worth meeting</figcaption></figure>$h$, 16, '2026-11-27') on conflict (id) do update set topic = excluded.topic, title = excluded.title, summary = excluded.summary, tags = excluded.tags, popular = excluded.popular, html = excluded.html, position = excluded.position, updated_on = excluded.updated_on;
insert into help_articles (id, topic, title, summary, tags, popular, html, position, updated_on) values ($h$block-member$h$, $h$network$h$, $h$Block a member$h$, $h$Stop someone contacting you and hide their content.$h$, $h$block mute harassment$h$, false, $h$<ol class="steps"><li>Open the member’s profile, or the menu on one of their posts.</li><li>Select <b>Block</b>.</li></ol><p>When you block someone:</p><ul><li>You won’t see each other’s posts, comments or stories.</li><li>They can’t message you or send you a connection request.</li><li>They are not told that you blocked them.</li></ul><p>To undo, go to <b>Me</b>, then <b>Blocked members</b>, and select <b>Unblock</b>. See also <a href="#/a/report-content">Report a post, member, business or review</a>.</p><figure class="fig"><button type="button" class="zoom" data-zoom="media/network-block.webp" aria-label="Enlarge screenshot: Block is at the bottom of the post menu"><img src="media/network-block.webp" alt="Block is at the bottom of the post menu" loading="lazy"></button><figcaption>Block is at the bottom of the post menu</figcaption></figure>$h$, 17, '2026-11-27') on conflict (id) do update set topic = excluded.topic, title = excluded.title, summary = excluded.summary, tags = excluded.tags, popular = excluded.popular, html = excluded.html, position = excluded.position, updated_on = excluded.updated_on;
insert into help_articles (id, topic, title, summary, tags, popular, html, position, updated_on) values ($h$post-types$h$, $h$feed$h$, $h$Post types: Question, Win, Offer, Hiring, Intro$h$, $h$Choose the right label so the right people see your post.$h$, $h$question win offer hiring intro tag$h$, true, $h$<p>When you write a post, choose a type. The type shows as a coloured tag and helps members filter the feed.</p><div class="tw"><table><thead><tr><th>Type</th><th>Use it for</th></tr></thead><tbody><tr><td>Question</td><td>Ask the community for advice</td></tr><tr><td>Win</td><td>Share a result, a milestone or a lesson learned</td></tr><tr><td>Offer</td><td>A deal or service for members (paid plans only)</td></tr><tr><td>Hiring</td><td>A job, a contract or a call for freelancers</td></tr><tr><td>Intro</td><td>Introduce yourself or your business</td></tr></tbody></table></div><div class="call plan"><b>Plans</b><span>Only Plus and Advisor members can post <b>Offers</b>: 2 a month on Plus, 4 a month on Advisor. This keeps the feed useful instead of full of ads.</span></div><figure class="fig"><button type="button" class="zoom" data-zoom="media/feed-composer.webp" aria-label="Enlarge screenshot: Choose a post type when you write a post"><img src="media/feed-composer.webp" alt="Choose a post type when you write a post" loading="lazy"></button><figcaption>Choose a post type when you write a post</figcaption></figure><figure class="fig"><button type="button" class="zoom" data-zoom="media/feed-offerlock.webp" aria-label="Enlarge screenshot: What Free members see when they choose Offer"><img src="media/feed-offerlock.webp" alt="What Free members see when they choose Offer" loading="lazy"></button><figcaption>What Free members see when they choose Offer</figcaption></figure>$h$, 18, '2026-11-27') on conflict (id) do update set topic = excluded.topic, title = excluded.title, summary = excluded.summary, tags = excluded.tags, popular = excluded.popular, html = excluded.html, position = excluded.position, updated_on = excluded.updated_on;
insert into help_articles (id, topic, title, summary, tags, popular, html, position, updated_on) values ($h$write-post$h$, $h$feed$h$, $h$Write a post$h$, $h$Add a title, photo, poll, hashtags or a group, or schedule it for later.$h$, $h$post create poll schedule photo$h$, true, $h$<figure class="fig vid"><div class="vbox"><video src="media/vid-post.mp4" poster="media/vid-post.jpg" muted loop playsinline preload="none" aria-label="Video walkthrough: Writing and publishing a Hiring post"></video><button type="button" class="vplay" aria-label="Play walkthrough">&#9654;</button></div><figcaption><span class="vtag">Walkthrough</span>Writing and publishing a Hiring post</figcaption></figure><ol class="steps"><li>On <b>Home</b>, select the box at the top of the feed.</li><li>Choose a post type. See <a href="#/a/post-types">Post types: Question, Win, Offer, Hiring, Intro</a>.</li><li>Write your post. Add a <b>title</b> if you like.</li><li>Optional extras:<ul><li><b>Photo:</b> add an image. You can choose to show it as a large cover.</li><li><b>Poll:</b> add answer options and how long the poll stays open.</li><li><b>Hashtags:</b> type # and a word, for example #cashflow. See <a href="#/a/hashtags">Use and follow hashtags</a>.</li><li><b>Group:</b> post into one of your groups instead of the main feed.</li><li><b>Schedule:</b> choose a date and time to publish later.</li></ul></li><li>Select <b>Post</b>.</li></ol><div class="call tip"><b>Tip</b><span>Questions get more replies when they include your industry, your city and what you have already tried.</span></div>$h$, 19, '2026-11-27') on conflict (id) do update set topic = excluded.topic, title = excluded.title, summary = excluded.summary, tags = excluded.tags, popular = excluded.popular, html = excluded.html, position = excluded.position, updated_on = excluded.updated_on;
insert into help_articles (id, topic, title, summary, tags, popular, html, position, updated_on) values ($h$edit-delete-post$h$, $h$feed$h$, $h$Edit or delete a post$h$, $h$Fix a typo soon after posting, or remove a post.$h$, $h$edit delete typo$h$, false, $h$<ul><li><b>Edit:</b> open the menu on your post and select <b>Edit</b>. You can edit for a short time after posting (10 minutes by default). Edited posts show "Edited".</li><li><b>Delete:</b> open the menu and select <b>Delete post</b>. This can’t be undone.</li></ul><p>Comments can also be edited for a short time after you write them.</p>$h$, 20, '2026-11-27') on conflict (id) do update set topic = excluded.topic, title = excluded.title, summary = excluded.summary, tags = excluded.tags, popular = excluded.popular, html = excluded.html, position = excluded.position, updated_on = excluded.updated_on;
insert into help_articles (id, topic, title, summary, tags, popular, html, position, updated_on) values ($h$reactions-comments$h$, $h$feed$h$, $h$Reactions, comments and reposts$h$, $h$Six reactions, threaded replies, and sharing to your followers.$h$, $h$like react comment repost share$h$, false, $h$<h3>Reactions</h3><p>Hover over or press and hold <b>Like</b> to choose: Like, Celebrate, Support, Love, Insightful or Funny.</p><h3>Comments</h3><p>Select <b>Comment</b> to reply. Select <b>Reply</b> under a comment to start a thread.</p><h3>Repost and share</h3><ul><li><b>Repost</b> shares the post to your followers, with an optional comment of your own.</li><li><b>Share</b> copies a link or shares it outside SME Hub, for example on LinkedIn.</li><li><b>Send in a message</b> sends it privately to a member.</li></ul><figure class="fig"><button type="button" class="zoom" data-zoom="media/feed-react.webp" aria-label="Enlarge screenshot: Pick a reaction"><img src="media/feed-react.webp" alt="Pick a reaction" loading="lazy"></button><figcaption>Pick a reaction</figcaption></figure>$h$, 21, '2026-11-27') on conflict (id) do update set topic = excluded.topic, title = excluded.title, summary = excluded.summary, tags = excluded.tags, popular = excluded.popular, html = excluded.html, position = excluded.position, updated_on = excluded.updated_on;
insert into help_articles (id, topic, title, summary, tags, popular, html, position, updated_on) values ($h$feed-filters$h$, $h$feed$h$, $h$Filter and save posts in your feed$h$, $h$Show only certain updates, save posts and hide ones you don’t want.$h$, $h$filter saved bookmark hide pinned$h$, false, $h$<p>Use the filter at the top of the feed to show:</p><ul><li>All updates</li><li>Created by me</li><li>I have reacted to</li><li>From my groups</li><li>From my connections</li><li>From people I follow</li><li>I am mentioned in</li><li>Hashtags I follow</li></ul><p>New posts load as you scroll. There is no "Load more" button.</p><h3>Save and hide</h3><ul><li>Select the <b>bookmark</b> on a post to save it. Find saved posts in your left menu.</li><li>Open the post menu and select <b>Hide this post</b> to remove it from your feed.</li></ul><div class="call note"><b>Good to know</b><span>Posts with a pin are pinned by the Hub team because they matter to everyone.</span></div><figure class="fig"><button type="button" class="zoom" data-zoom="media/feed-tools.webp" aria-label="Enlarge screenshot: The feed filter and sort, above the posts"><img src="media/feed-tools.webp" alt="The feed filter and sort, above the posts" loading="lazy"></button><figcaption>The feed filter and sort, above the posts</figcaption></figure>$h$, 22, '2026-11-27') on conflict (id) do update set topic = excluded.topic, title = excluded.title, summary = excluded.summary, tags = excluded.tags, popular = excluded.popular, html = excluded.html, position = excluded.position, updated_on = excluded.updated_on;
insert into help_articles (id, topic, title, summary, tags, popular, html, position, updated_on) values ($h$translate-post$h$, $h$feed$h$, $h$Translate a post to French or English$h$, $h$Read posts in the other official language with one click.$h$, $h$french translation language bilingual$h$, false, $h$<p>Open the menu on a post and select <b>Translate to French (AI)</b> (or English). The translation shows with an <b>AI</b> label. Select <b>Show original</b> to switch back.</p><div class="call note"><b>Good to know</b><span>AI translations can be imperfect. If something matters, check with the author.</span></div><figure class="fig"><button type="button" class="zoom" data-zoom="media/feed-translate.webp" aria-label="Enlarge screenshot: A post translated to French, with the AI label"><img src="media/feed-translate.webp" alt="A post translated to French, with the AI label" loading="lazy"></button><figcaption>A post translated to French, with the AI label</figcaption></figure>$h$, 23, '2026-11-27') on conflict (id) do update set topic = excluded.topic, title = excluded.title, summary = excluded.summary, tags = excluded.tags, popular = excluded.popular, html = excluded.html, position = excluded.position, updated_on = excluded.updated_on;
insert into help_articles (id, topic, title, summary, tags, popular, html, position, updated_on) values ($h$what-are-stories$h$, $h$stories$h$, $h$What are Stories?$h$, $h$Short photo and video updates that disappear after 24 hours.$h$, $h$story stories 24 hours$h$, true, $h$<p>Stories are quick, informal updates, such as a new product, a busy day at the shop or a trade show stand. They show in the row of circles at the top of your Home feed and on profiles.</p><ul><li>A coloured ring around a photo or logo means there is a story you haven’t seen.</li><li>Stories disappear after <b>24 hours</b> unless the author saves them to a <b>highlight</b> on their profile.</li><li>Businesses can post stories too. A ring appears around their logo.</li></ul><figure class="fig"><button type="button" class="zoom" data-zoom="media/stories-row.webp" aria-label="Enlarge screenshot: The stories row at the top of Home. Select Your story to add one"><img src="media/stories-row.webp" alt="The stories row at the top of Home. Select Your story to add one" loading="lazy"></button><figcaption>The stories row at the top of Home. Select Your story to add one</figcaption></figure>$h$, 24, '2026-11-27') on conflict (id) do update set topic = excluded.topic, title = excluded.title, summary = excluded.summary, tags = excluded.tags, popular = excluded.popular, html = excluded.html, position = excluded.position, updated_on = excluded.updated_on;
insert into help_articles (id, topic, title, summary, tags, popular, html, position, updated_on) values ($h$post-story$h$, $h$stories$h$, $h$Post a story$h$, $h$Add up to 5 photos or videos, pick who sees it and share.$h$, $h$create upload story video$h$, false, $h$<figure class="fig vid"><div class="vbox"><video src="media/vid-story.mp4" poster="media/vid-story.jpg" muted loop playsinline preload="none" aria-label="Video walkthrough: Posting a photo story"></video><button type="button" class="vplay" aria-label="Play walkthrough">&#9654;</button></div><figcaption><span class="vtag">Walkthrough</span>Posting a photo story</figcaption></figure><ol class="steps"><li>On <b>Home</b>, select <b>Your story</b> (the first circle).</li><li>Select <b>Add photos or videos</b>. You can add up to 5 per story.</li><li>Add a caption if you like.</li><li>Under <b>Who can see this</b>, choose an audience. See <a href="#/a/story-audience">Who can see my story?</a>.</li><li>If you are on a business team, use <b>Posting as</b> to choose <b>Myself</b> or your business.</li><li>Select <b>Publish story</b>. Select <b>Preview</b> first if you want to check it.</li></ol><div class="tw"><table><thead><tr><th>Limit</th><th>Default</th></tr></thead><tbody><tr><td>Items per story</td><td>5</td></tr><tr><td>File types</td><td>JPG, PNG, WebP, MP4, MOV, WebM</td></tr><tr><td>File size</td><td>Up to 25 MB each</td></tr><tr><td>Video length</td><td>Up to 30 seconds</td></tr><tr><td>Live stories at a time</td><td>3</td></tr></tbody></table></div><div class="call tip"><b>Tip</b><span>Upright (portrait) photos and videos fill the screen best: 1080 × 1920 pixels.</span></div><figure class="fig"><button type="button" class="zoom" data-zoom="media/stories-new.webp" aria-label="Enlarge screenshot: The New story window"><img src="media/stories-new.webp" alt="The New story window" loading="lazy"></button><figcaption>The New story window</figcaption></figure>$h$, 25, '2026-11-27') on conflict (id) do update set topic = excluded.topic, title = excluded.title, summary = excluded.summary, tags = excluded.tags, popular = excluded.popular, html = excluded.html, position = excluded.position, updated_on = excluded.updated_on;
insert into help_articles (id, topic, title, summary, tags, popular, html, position, updated_on) values ($h$story-audience$h$, $h$stories$h$, $h$Who can see my story?$h$, $h$All Hub members or My connections, and what each one means.$h$, $h$audience privacy connections$h$, false, $h$<div class="tw"><table><thead><tr><th>Choice</th><th>Who sees it</th></tr></thead><tbody><tr><td>All Hub members</td><td>All signed-in SME Hub members (the default)</td></tr><tr><td>My connections</td><td>Only members you are connected with</td></tr></tbody></table></div><p>People who have not joined never see members-only stories.</p><div class="call note"><b>Good to know</b><span>The Hub team can change which choices are available.</span></div>$h$, 26, '2026-11-27') on conflict (id) do update set topic = excluded.topic, title = excluded.title, summary = excluded.summary, tags = excluded.tags, popular = excluded.popular, html = excluded.html, position = excluded.position, updated_on = excluded.updated_on;
insert into help_articles (id, topic, title, summary, tags, popular, html, position, updated_on) values ($h$view-stories$h$, $h$stories$h$, $h$Watch, like and report stories$h$, $h$How the story viewer works.$h$, $h$viewer watch like report$h$, false, $h$<ul><li>Tap a circle to open the story. It plays full screen.</li><li>Tap the right side, or the arrow, to go forward. Tap the left side to go back.</li><li>Tap <b>pause</b> to stop. Tap the <b>heart</b> to like.</li><li>Open the <b>…</b> menu to report a story.</li><li>On your own stories, you can see who viewed them.</li></ul><figure class="fig vid"><div class="vbox"><video src="media/vid-storyview.mp4" poster="media/vid-storyview.jpg" muted loop playsinline preload="none" aria-label="Video walkthrough: Watching, moving to the next story and liking"></video><button type="button" class="vplay" aria-label="Play walkthrough">&#9654;</button></div><figcaption><span class="vtag">Walkthrough</span>Watching, moving to the next story and liking</figcaption></figure><figure class="fig"><button type="button" class="zoom" data-zoom="media/stories-viewer.webp" aria-label="Enlarge screenshot: The story viewer"><img src="media/stories-viewer.webp" alt="The story viewer" loading="lazy"></button><figcaption>The story viewer</figcaption></figure>$h$, 27, '2026-11-27') on conflict (id) do update set topic = excluded.topic, title = excluded.title, summary = excluded.summary, tags = excluded.tags, popular = excluded.popular, html = excluded.html, position = excluded.position, updated_on = excluded.updated_on;
insert into help_articles (id, topic, title, summary, tags, popular, html, position, updated_on) values ($h$highlights$h$, $h$stories$h$, $h$Keep stories as highlights$h$, $h$Save stories to your profile after they expire.$h$, $h$highlight profile save$h$, false, $h$<p>Highlights keep your best stories on your profile, grouped by name, for example "Our Products" or "Behind the Scenes".</p><ol class="steps"><li>Open your profile and go to <b>Stories and highlights</b>.</li><li>Select <b>New highlight</b>, give it a name and choose stories to add.</li><li>To change one, open it and choose <b>Edit</b> or <b>Delete</b>.</li></ol><figure class="fig"><button type="button" class="zoom" data-zoom="media/stories-highlights.webp" aria-label="Enlarge screenshot: Stories and highlights on a profile"><img src="media/stories-highlights.webp" alt="Stories and highlights on a profile" loading="lazy"></button><figcaption>Stories and highlights on a profile</figcaption></figure>$h$, 28, '2026-11-27') on conflict (id) do update set topic = excluded.topic, title = excluded.title, summary = excluded.summary, tags = excluded.tags, popular = excluded.popular, html = excluded.html, position = excluded.position, updated_on = excluded.updated_on;
insert into help_articles (id, topic, title, summary, tags, popular, html, position, updated_on) values ($h$delete-story$h$, $h$stories$h$, $h$Delete a story$h$, $h$Remove a story before it expires.$h$, $h$remove delete$h$, false, $h$<p>Open your story, select the <b>…</b> menu, then <b>Delete</b>. It is removed from the feed, your profile and any highlights.</p>$h$, 29, '2026-11-27') on conflict (id) do update set topic = excluded.topic, title = excluded.title, summary = excluded.summary, tags = excluded.tags, popular = excluded.popular, html = excluded.html, position = excluded.position, updated_on = excluded.updated_on;
insert into help_articles (id, topic, title, summary, tags, popular, html, position, updated_on) values ($h$join-group$h$, $h$groups$h$, $h$Find and join groups$h$, $h$Browse groups by topic, industry, community and city.$h$, $h$join group community$h$, true, $h$<figure class="fig vid"><div class="vbox"><video src="media/vid-group.mp4" poster="media/vid-group.jpg" muted loop playsinline preload="none" aria-label="Video walkthrough: Joining a group and opening it"></video><button type="button" class="vplay" aria-label="Play walkthrough">&#9654;</button></div><figcaption><span class="vtag">Walkthrough</span>Joining a group and opening it</figcaption></figure><ol class="steps"><li>Open <b>Explore</b>, then <b>Groups</b>.</li><li>Browse by category, or search.</li><li>Select a group to see what it is about, who runs it and recent posts.</li><li>Select <b>Join</b>.</li></ol><div class="tw"><table><thead><tr><th>Group type</th><th>How you join</th></tr></thead><tbody><tr><td>Public group</td><td>Join straight away</td></tr><tr><td>Private group or circle</td><td>Select <b>Request to join</b>. A group organiser approves you</td></tr></tbody></table></div><div class="call tip"><b>Tip</b><span>Start with two groups: one for your industry and one for a challenge you’re working on, for example money or hiring.</span></div><figure class="fig"><button type="button" class="zoom" data-zoom="media/groups-list.webp" aria-label="Enlarge screenshot: The Groups page"><img src="media/groups-list.webp" alt="The Groups page" loading="lazy"></button><figcaption>The Groups page</figcaption></figure>$h$, 30, '2026-11-27') on conflict (id) do update set topic = excluded.topic, title = excluded.title, summary = excluded.summary, tags = excluded.tags, popular = excluded.popular, html = excluded.html, position = excluded.position, updated_on = excluded.updated_on;
insert into help_articles (id, topic, title, summary, tags, popular, html, position, updated_on) values ($h$create-group$h$, $h$groups$h$, $h$Create a group$h$, $h$Who can create groups and how.$h$, $h$start new group private circle$h$, false, $h$<div class="call plan"><b>Plans</b><span><b>Private groups</b> (for example a client circle) are for paid members: Plus members can host 1 and Advisor members can host 3. <b>Public groups</b> can be requested by any member and are approved by the Hub team.</span></div><ol class="steps"><li>Open <b>Groups</b> and select <b>Start a group</b>.</li><li>Choose the kind of group:<ul><li><b>Ask for a public group:</b> a topic, industry or regional group in the main directory. Select <b>Request a public group</b>. The Hub team reviews it.</li><li><b>Create a private group:</b> your own space, such as a client circle or a mastermind. Available on Plus and Advisor.</li></ul></li><li>Add a name, description and cover image, then create or send your request.</li></ol><figure class="fig"><button type="button" class="zoom" data-zoom="media/groups-new.webp" aria-label="Enlarge screenshot: The Start a group window"><img src="media/groups-new.webp" alt="The Start a group window" loading="lazy"></button><figcaption>The Start a group window</figcaption></figure>$h$, 31, '2026-11-27') on conflict (id) do update set topic = excluded.topic, title = excluded.title, summary = excluded.summary, tags = excluded.tags, popular = excluded.popular, html = excluded.html, position = excluded.position, updated_on = excluded.updated_on;
insert into help_articles (id, topic, title, summary, tags, popular, html, position, updated_on) values ($h$run-group$h$, $h$groups$h$, $h$Run your group$h$, $h$Approve members, message everyone and keep the group on track.$h$, $h$moderate organiser admin$h$, false, $h$<p>As a group organiser you can:</p><ul><li>Approve or decline requests to join a private group.</li><li>Post announcements and pin important posts.</li><li><b>Message all members</b> at once.</li><li>Remove members or report posts that break the rules.</li><li>Archive the group when it is no longer active.</li></ul><p>SME Hub’s community guidelines apply in every group. See <a href="#/a/community-guidelines">Community guidelines</a>.</p><figure class="fig"><button type="button" class="zoom" data-zoom="media/groups-page.webp" aria-label="Enlarge screenshot: A group page with its feed, host and members"><img src="media/groups-page.webp" alt="A group page with its feed, host and members" loading="lazy"></button><figcaption>A group page with its feed, host and members</figcaption></figure>$h$, 32, '2026-11-27') on conflict (id) do update set topic = excluded.topic, title = excluded.title, summary = excluded.summary, tags = excluded.tags, popular = excluded.popular, html = excluded.html, position = excluded.position, updated_on = excluded.updated_on;
insert into help_articles (id, topic, title, summary, tags, popular, html, position, updated_on) values ($h$leave-group$h$, $h$groups$h$, $h$Leave a group$h$, $h$Stop seeing a group in your feed.$h$, $h$leave exit$h$, false, $h$<p>Open the group and select <b>Joined</b>, then <b>Leave group</b>. To rejoin a private group later, you’ll need to request again.</p>$h$, 33, '2026-11-27') on conflict (id) do update set topic = excluded.topic, title = excluded.title, summary = excluded.summary, tags = excluded.tags, popular = excluded.popular, html = excluded.html, position = excluded.position, updated_on = excluded.updated_on;
insert into help_articles (id, topic, title, summary, tags, popular, html, position, updated_on) values ($h$messaging-basics$h$, $h$messages$h$, $h$Send a message$h$, $h$Use the chat window or the full Messages page.$h$, $h$chat dm inbox$h$, true, $h$<figure class="fig vid"><div class="vbox"><video src="media/vid-message.mp4" poster="media/vid-message.jpg" muted loop playsinline preload="none" aria-label="Video walkthrough: Replying from the Messaging window"></video><button type="button" class="vplay" aria-label="Play walkthrough">&#9654;</button></div><figcaption><span class="vtag">Walkthrough</span>Replying from the Messaging window</figcaption></figure><ol class="steps"><li>Select <b>Message</b> on a member’s profile or card, or open <b>Messaging</b> in the bottom-right corner of any page.</li><li>Write your message and press <b>Send</b>.</li></ol><p>The <b>Messages</b> page shows all your conversations on one screen, with unread counts.</p><div class="call note"><b>Good to know</b><span>Be specific in a first message. Unsolicited sales pitches break the community guidelines and can be reported.</span></div><figure class="fig"><button type="button" class="zoom" data-zoom="media/msg-page.webp" aria-label="Enlarge screenshot: The Messages page"><img src="media/msg-page.webp" alt="The Messages page" loading="lazy"></button><figcaption>The Messages page</figcaption></figure>$h$, 34, '2026-11-27') on conflict (id) do update set topic = excluded.topic, title = excluded.title, summary = excluded.summary, tags = excluded.tags, popular = excluded.popular, html = excluded.html, position = excluded.position, updated_on = excluded.updated_on;
insert into help_articles (id, topic, title, summary, tags, popular, html, position, updated_on) values ($h$message-business$h$, $h$messages$h$, $h$Message a business$h$, $h$Contact a business page. The whole business team can answer.$h$, $h$business inquiry quote contact$h$, false, $h$<ol class="steps"><li>Open the business page.</li><li>Select <b>Message business</b> (on phones, it sits at the bottom of the screen).</li><li>Write your message, for example a question or a quote request, and select <b>Send</b>. Replies arrive in your Messages.</li></ol><p>Messages to a business go to the business’s shared inbox. The owner and team members with inbox access can reply as the business.</p><figure class="fig"><button type="button" class="zoom" data-zoom="media/biz-inquiry.webp" aria-label="Enlarge screenshot: Messaging a business"><img src="media/biz-inquiry.webp" alt="Messaging a business" loading="lazy"></button><figcaption>Messaging a business</figcaption></figure>$h$, 35, '2026-11-27') on conflict (id) do update set topic = excluded.topic, title = excluded.title, summary = excluded.summary, tags = excluded.tags, popular = excluded.popular, html = excluded.html, position = excluded.position, updated_on = excluded.updated_on;
insert into help_articles (id, topic, title, summary, tags, popular, html, position, updated_on) values ($h$notifications$h$, $h$messages$h$, $h$Notifications$h$, $h$What the bell shows and how to manage it.$h$, $h$alerts bell email$h$, false, $h$<p>The <b>bell</b> at the top shows a red number when something new happens, such as:</p><ul><li>Reactions, comments and mentions on your posts</li><li>Connection requests and introductions</li><li>New recommendations</li><li>Messages to you or your business</li><li>Updates on business pages, reviews and approvals</li><li>Decisions on things you reported</li></ul><p>Open the bell to see them.</p><h3>Email notifications</h3><p>We also email you about things you might miss, such as messages you haven’t read, connection requests and a weekly summary. Similar emails are grouped, so you get at most one an hour about mentions and replies.</p><p>To choose which emails you get, go to <b>Me</b>, then <b>Settings</b>, then <b>Email notifications</b>. Every notification email also has a link at the bottom to change your settings or turn that type off.</p><div class="call note"><b>Good to know</b><span>Security, billing and important legal emails are always sent, even if you turn off everything else. See <a href="#/a/emails-from-us">Emails from SME Hub, and how to spot fakes</a>.</span></div><figure class="fig"><button type="button" class="zoom" data-zoom="media/msg-bell.webp" aria-label="Enlarge screenshot: Your notifications"><img src="media/msg-bell.webp" alt="Your notifications" loading="lazy"></button><figcaption>Your notifications</figcaption></figure>$h$, 36, '2026-11-27') on conflict (id) do update set topic = excluded.topic, title = excluded.title, summary = excluded.summary, tags = excluded.tags, popular = excluded.popular, html = excluded.html, position = excluded.position, updated_on = excluded.updated_on;
insert into help_articles (id, topic, title, summary, tags, popular, html, position, updated_on) values ($h$add-business$h$, $h$business$h$, $h$Add your business to the directory$h$, $h$Create a free business page in five quick details.$h$, $h$list create business page directory$h$, true, $h$<figure class="fig vid"><div class="vbox"><video src="media/vid-addbiz.mp4" poster="media/vid-addbiz.jpg" muted loop playsinline preload="none" aria-label="Video walkthrough: Adding a business in five quick details"></video><button type="button" class="vplay" aria-label="Play walkthrough">&#9654;</button></div><figcaption><span class="vtag">Walkthrough</span>Adding a business in five quick details</figcaption></figure><ol class="steps"><li>Open <b>Business Directory</b> and select <b>Add a business</b> (or go to <b>Me</b>, then <b>My businesses</b>).</li><li>Fill in the five quick details: <b>business name</b>, <b>category</b>, <b>how customers reach you</b> (storefront or office, you go to them, or online), a <b>short description</b>, and your <b>city and province</b>.</li><li>If SME Hub finds a similar business already listed, check it first. It may be yours to claim. See <a href="#/a/claim-business">Claim a business that is already listed</a>.</li><li>Select <b>Save draft and add more details</b> (or <b>Save draft and preview</b>). Only you can see the draft.</li><li>Add your logo, header image, hours, services, photos and contact details.</li><li>Select <b>Submit for review</b>. The CanadianSME team checks new pages before they go live.</li></ol><div class="call tip"><b>Tip</b><span>Have a website? On your Home page, select <b>Set it up for me</b> and paste your website or Google listing. AI fills in the five details and a description for you. See <a href="#/a/first-week">Get your profile ready</a>.</span></div><div class="call plan"><b>Plans</b><span>The Free plan includes one business page. Plus and Advisor members can own up to 3, and their listings are featured first in the directory.</span></div><figure class="fig"><button type="button" class="zoom" data-zoom="media/biz-add.webp" aria-label="Enlarge screenshot: The Add a business form"><img src="media/biz-add.webp" alt="The Add a business form" loading="lazy"></button><figcaption>The Add a business form</figcaption></figure>$h$, 37, '2026-11-27') on conflict (id) do update set topic = excluded.topic, title = excluded.title, summary = excluded.summary, tags = excluded.tags, popular = excluded.popular, html = excluded.html, position = excluded.position, updated_on = excluded.updated_on;
insert into help_articles (id, topic, title, summary, tags, popular, html, position, updated_on) values ($h$claim-business$h$, $h$business$h$, $h$Claim a business that is already listed$h$, $h$Take over a listing the CanadianSME team created.$h$, $h$claim ownership verify$h$, false, $h$<p>Some businesses were added by the CanadianSME team. If one of them is yours:</p><ol class="steps"><li>Open the business page.</li><li>Select <b>Claim this business</b>.</li><li>Tell us your role and how we can verify it, for example a business email at the same domain.</li><li>The team reviews the claim. Once approved, you become the owner and can manage the page.</li></ol><figure class="fig"><button type="button" class="zoom" data-zoom="media/biz-claim.webp" aria-label="Enlarge screenshot: The Claim this business form"><img src="media/biz-claim.webp" alt="The Claim this business form" loading="lazy"></button><figcaption>The Claim this business form</figcaption></figure>$h$, 38, '2026-11-27') on conflict (id) do update set topic = excluded.topic, title = excluded.title, summary = excluded.summary, tags = excluded.tags, popular = excluded.popular, html = excluded.html, position = excluded.position, updated_on = excluded.updated_on;
insert into help_articles (id, topic, title, summary, tags, popular, html, position, updated_on) values ($h$manage-business$h$, $h$business$h$, $h$Manage your business page$h$, $h$See all your business pages in one place, and edit details, hours, services, inbox and team.$h$, $h$edit page hours services photos$h$, true, $h$<h3>Your businesses at a glance</h3><p>Open <b>Me</b>, then <b>My businesses</b>. Each page you own or help run has its own card with:</p><ul><li>Whether it’s <b>Live</b>, a <b>Draft</b> or <b>Waiting for review</b></li><li>Followers, page views, inquiries, reviews and updates</li><li>Quick buttons to post an update, answer inquiries, change your hours, see your team and copy the page link</li><li><b>How complete your page is</b>: open it to see the steps left, like adding a logo or photos. Each step takes you straight to the right place.</li></ul><figure class="fig"><button type="button" class="zoom" data-zoom="media/my-businesses.webp" aria-label="Enlarge screenshot: A business on the My businesses page"><img src="media/my-businesses.webp" alt="A business on the My businesses page" loading="lazy"></button><figcaption>A business on the My businesses page</figcaption></figure><p>Any ownership claims you’ve sent show below, with where each one is: sent, under review, then approved or not approved.</p><h3>Manage a page</h3><p>Select <b>Manage page</b>. The tabs are:</p><ul><li><b>Details:</b> name, category, description, address, area served and contact details. Use the switches to choose which details show publicly. For example, hide your street address if you work from home.</li><li><b>Hours:</b> opening hours for each day, appointment-only hours and holiday closures. Your page shows <b>Open now</b> or <b>Closed</b> in your local time zone.</li><li><b>Services:</b> what you offer, with optional prices.</li><li><b>Photos, Shop, Events, Jobs:</b> optional tabs you can fill in.</li><li><b>Inbox:</b> messages and quote requests.</li><li><b>Reviews:</b> read and reply to reviews.</li><li><b>Team:</b> invite people and choose their role. See <a href="#/a/business-roles">Business team roles</a>.</li><li><b>Publish and share:</b> see how your page looks when shared, and copy the link.</li></ul><figure class="fig"><button type="button" class="zoom" data-zoom="media/biz-manage.webp" aria-label="Enlarge screenshot: Managing a business page: the tabs across the top"><img src="media/biz-manage.webp" alt="Managing a business page: the tabs across the top" loading="lazy"></button><figcaption>Managing a business page: the tabs across the top</figcaption></figure>$h$, 39, '2026-11-27') on conflict (id) do update set topic = excluded.topic, title = excluded.title, summary = excluded.summary, tags = excluded.tags, popular = excluded.popular, html = excluded.html, position = excluded.position, updated_on = excluded.updated_on;
insert into help_articles (id, topic, title, summary, tags, popular, html, position, updated_on) values ($h$business-roles$h$, $h$business$h$, $h$Business team roles$h$, $h$Owner, Manager, Editor and Inbox: who can do what.$h$, $h$team roles permissions staff$h$, false, $h$<div class="tw"><table><thead><tr><th>Role</th><th>Can do</th></tr></thead><tbody><tr><td>Owner</td><td>Everything: details, updates, inquiries, the team and the page itself</td></tr><tr><td>Manager</td><td>Edit details, post updates and stories, answer inquiries</td></tr><tr><td>Editor</td><td>Post updates and stories as the business</td></tr><tr><td>Inbox</td><td>Read and answer inquiries as the business</td></tr></tbody></table></div><p>Only the owner can add or remove team members and change roles.</p><figure class="fig"><button type="button" class="zoom" data-zoom="media/biz-team.webp" aria-label="Enlarge screenshot: The Team tab, where the owner sets roles"><img src="media/biz-team.webp" alt="The Team tab, where the owner sets roles" loading="lazy"></button><figcaption>The Team tab, where the owner sets roles</figcaption></figure>$h$, 40, '2026-11-27') on conflict (id) do update set topic = excluded.topic, title = excluded.title, summary = excluded.summary, tags = excluded.tags, popular = excluded.popular, html = excluded.html, position = excluded.position, updated_on = excluded.updated_on;
insert into help_articles (id, topic, title, summary, tags, popular, html, position, updated_on) values ($h$post-as-business$h$, $h$business$h$, $h$Post and reply as your business$h$, $h$Share updates and stories that show your business as the author.$h$, $h$business update post as company$h$, false, $h$<p>If you are an owner, manager or editor of a business, you can post as the business.</p><ol class="steps"><li>In the post or story window, choose your business under <b>Posting as</b>.</li><li>Write your update and post.</li></ol><p>Members see your business name and logo as the author. Only your team sees which person posted it.</p><figure class="fig"><button type="button" class="zoom" data-zoom="media/stories-new.webp" aria-label="Enlarge screenshot: Use Posting as to choose your business"><img src="media/stories-new.webp" alt="Use Posting as to choose your business" loading="lazy"></button><figcaption>Use Posting as to choose your business</figcaption></figure>$h$, 41, '2026-11-27') on conflict (id) do update set topic = excluded.topic, title = excluded.title, summary = excluded.summary, tags = excluded.tags, popular = excluded.popular, html = excluded.html, position = excluded.position, updated_on = excluded.updated_on;
insert into help_articles (id, topic, title, summary, tags, popular, html, position, updated_on) values ($h$business-reviews$h$, $h$business$h$, $h$Reviews of businesses$h$, $h$How reviews and ratings work, and how to reply.$h$, $h$rating stars review reply$h$, false, $h$<p>Members can review businesses they have used. They rate <b>Quality</b>, <b>Value</b> and <b>Communication</b>, then write a short review. The business page shows the average rating and the number of reviews.</p><ul><li><b>Owners and managers</b> can reply publicly to each review.</li><li>If a review is fake or breaks the rules, select <b>Report</b>. See <a href="#/a/report-content">Report a post, member, business or review</a>.</li></ul><div class="call note"><b>Good to know</b><span>Reviews must be honest and based on real experience. Reviewing your own business, or offering rewards for reviews, is not allowed.</span></div><figure class="fig"><button type="button" class="zoom" data-zoom="media/biz-reviews.webp" aria-label="Enlarge screenshot: Ratings and reviews on a business page"><img src="media/biz-reviews.webp" alt="Ratings and reviews on a business page" loading="lazy"></button><figcaption>Ratings and reviews on a business page</figcaption></figure>$h$, 42, '2026-11-27') on conflict (id) do update set topic = excluded.topic, title = excluded.title, summary = excluded.summary, tags = excluded.tags, popular = excluded.popular, html = excluded.html, position = excluded.position, updated_on = excluded.updated_on;
insert into help_articles (id, topic, title, summary, tags, popular, html, position, updated_on) values ($h$search-directory$h$, $h$business$h$, $h$Search the Business Directory$h$, $h$Find businesses by service, place, category and opening hours.$h$, $h$find search businesses map open now$h$, true, $h$<figure class="fig vid"><div class="vbox"><video src="media/vid-directory.mp4" poster="media/vid-directory.jpg" muted loop playsinline preload="none" aria-label="Video walkthrough: Searching, switching to the map and opening a business"></video><button type="button" class="vplay" aria-label="Play walkthrough">&#9654;</button></div><figcaption><span class="vtag">Walkthrough</span>Searching, switching to the map and opening a business</figcaption></figure><ol class="steps"><li>Select <b>Business Directory</b> in the top menu.</li><li>Type what you need, for example "bookkeeping" or "catering", and choose a province, or leave it as All of Canada.</li><li>Pick a category tile, or use <b>Filters</b>: category, province, city, how they serve you (visit in person, comes to you, online) and <b>Open now</b>.</li><li>Switch between <b>Grid</b>, <b>List</b> and <b>Map</b>, and sort by recommended, top rated, newest or name.</li><li>Select a business to see its page, then <b>Message business</b>, <b>Follow</b>, <b>Call</b> or <b>Visit website</b>.</li></ol><figure class="fig"><button type="button" class="zoom" data-zoom="media/biz-directory.webp" aria-label="Enlarge screenshot: The Business Directory"><img src="media/biz-directory.webp" alt="The Business Directory" loading="lazy"></button><figcaption>The Business Directory</figcaption></figure>$h$, 43, '2026-11-27') on conflict (id) do update set topic = excluded.topic, title = excluded.title, summary = excluded.summary, tags = excluded.tags, popular = excluded.popular, html = excluded.html, position = excluded.position, updated_on = excluded.updated_on;
insert into help_articles (id, topic, title, summary, tags, popular, html, position, updated_on) values ($h$follow-business$h$, $h$business$h$, $h$Follow a business$h$, $h$Get a business’s updates in your feed.$h$, $h$follow updates$h$, false, $h$<p>Select <b>+ Follow</b> on a business page or on one of its posts. Its updates and stories then show in your feed. Select <b>Following</b> to unfollow.</p><figure class="fig"><button type="button" class="zoom" data-zoom="media/biz-head.webp" aria-label="Enlarge screenshot: Follow, Message business, Call and Share on a business page"><img src="media/biz-head.webp" alt="Follow, Message business, Call and Share on a business page" loading="lazy"></button><figcaption>Follow, Message business, Call and Share on a business page</figcaption></figure>$h$, 44, '2026-11-27') on conflict (id) do update set topic = excluded.topic, title = excluded.title, summary = excluded.summary, tags = excluded.tags, popular = excluded.popular, html = excluded.html, position = excluded.position, updated_on = excluded.updated_on;
insert into help_articles (id, topic, title, summary, tags, popular, html, position, updated_on) values ($h$buy-a-business$h$, $h$business$h$, $h$Buy a business on SME Hub$h$, $h$Find a Canadian small business for sale and contact the seller.$h$, $h$buy business for sale acquisition purchase seller confidential owner earnings$h$, false, $h$<p><b>Businesses for sale</b> lists Canadian small businesses looking for a new owner. Every listing comes from a paid SME Hub member, and there is no broker in the middle.</p><h3>Find a business</h3><ol class="steps"><li>Open <b>Explore</b>, then <b>Businesses for Sale</b>. You can also select <b>Businesses for sale</b> on the Business Directory page.</li><li>Search by type of business, keyword or city, and pick a province.</li><li>Narrow the list by industry, asking price or type of sale.</li></ol><figure class="fig"><button type="button" class="zoom" data-zoom="media/forsale-browse.webp" aria-label="Enlarge screenshot: Browsing businesses for sale"><img src="media/forsale-browse.webp" alt="Browsing businesses for sale" loading="lazy"></button><figcaption>Browsing businesses for sale</figcaption></figure><p>Anyone can see the headline, area, industry and asking price. Signed-in members also see yearly sales, owner earnings, what’s included, why the owner is selling and who the seller is. Joining is free.</p><div class="call tip"><b>Tip</b><span><b>Owner earnings</b> is what the business earns for one full-time owner each year, before the owner’s pay, interest and tax. Ask the seller how they worked it out.</span></div><h3>Types of sale</h3><div class="tw"><table><thead><tr><th>Type</th><th>What it means</th></tr></thead><tbody><tr><td>Full sale</td><td>You buy the whole business.</td></tr><tr><td>Partner wanted (part stake)</td><td>The owner sells part of the business and stays on.</td></tr><tr><td>Assets only</td><td>You buy equipment, stock or the brand, but not the running business.</td></tr></tbody></table></div><h3>Contact the seller</h3><ol class="steps"><li>Open the listing and select <b>Contact the seller</b>.</li><li>Say how you’ll pay and when you want to buy, then write a short message about yourself.</li><li>Tick the box to agree to keep the seller’s details private.</li><li>Select <b>Send to the seller</b>. They reply in your messages.</li></ol><figure class="fig"><button type="button" class="zoom" data-zoom="media/forsale-listing.webp" aria-label="Enlarge screenshot: A listing, with the asking price and Contact the seller button"><img src="media/forsale-listing.webp" alt="A listing, with the asking price and Contact the seller button" loading="lazy"></button><figcaption>A listing, with the asking price and Contact the seller button</figcaption></figure><p>Some sellers stay confidential. You’ll see <b>Confidential seller</b> until they choose to share their name and documents with you.</p><h3>Save a listing</h3><p>Select the bookmark on any listing to save it. Your saved listings are on the <b>Saved</b> tab. We email you if the price changes or the business goes under offer.</p><h3>Buy safely</h3><ul><li>Ask an accountant to check the financial statements.</li><li>Use a lawyer for the offer and purchase agreement.</li><li>Never send money to hold a business. SME Hub never asks for payment.</li><li>If something looks wrong, select <b>Report this listing</b>. The seller won’t know who reported it.</li></ul><p>A shield and <b>Checked by the Hub team</b> means our team has checked that the seller is a real paid member and the listing follows our rules. It doesn’t mean we’ve checked the business’s accounts.</p>$h$, 45, '2026-11-27') on conflict (id) do update set topic = excluded.topic, title = excluded.title, summary = excluded.summary, tags = excluded.tags, popular = excluded.popular, html = excluded.html, position = excluded.position, updated_on = excluded.updated_on;
insert into help_articles (id, topic, title, summary, tags, popular, html, position, updated_on) values ($h$sell-your-business$h$, $h$business$h$, $h$Sell your business on SME Hub$h$, $h$List your business for sale, stay confidential and handle buyer enquiries.$h$, $h$sell business for sale listing exit retire confidential enquiries buyers$h$, false, $h$<div class="call plan"><b>Plans</b><span>Listing a business for sale is included with the <b>Plus</b> and <b>Advisor</b> plans. Browsing and contacting sellers is free for every member. See <a href="#/a/plans-compared">Free, Plus and Advisor plans compared</a>.</span></div><h3>List your business</h3><ol class="steps"><li>Open <b>Explore</b>, then <b>Businesses for Sale</b>, and select <b>Sell your business</b>.</li><li>Fill in the 5 short sections: the basics, price and numbers, about the business, what’s included, and photo and privacy. It takes about 10 minutes.</li><li>Check the preview on the right, then select <b>Publish listing</b>.</li></ol><figure class="fig"><button type="button" class="zoom" data-zoom="media/forsale-sell.webp" aria-label="Enlarge screenshot: The form for listing a business for sale"><img src="media/forsale-sell.webp" alt="The form for listing a business for sale" loading="lazy"></button><figcaption>The form for listing a business for sale</figcaption></figure><p>Your listing goes live straight away. The Hub team checks every new listing within 2 working days. Once it’s checked, buyers see a shield on it.</p><div class="call tip"><b>Tip</b><span>Listings with an asking price get far more enquiries than <b>Price on request</b>. Talk to an accountant about the value before you list.</span></div><h3>Stay confidential</h3><p><b>Keep my name and business name hidden</b> is on by default. Buyers see <b>Confidential seller</b> and only the area you choose, such as a neighbourhood or region. Leave your business name out of the headline and avoid photos of your shop sign.</p><p>You decide who learns more. When you select <b>Share documents and my name</b> on an enquiry, only that buyer sees your name and documents.</p><h3>Handle enquiries</h3><p>Open <b>My listings</b> to see views, saves and enquiries for each listing. Each enquiry shows how the buyer will pay, when they want to buy and their message.</p><figure class="fig"><button type="button" class="zoom" data-zoom="media/forsale-enquiries.webp" aria-label="Enlarge screenshot: Enquiries on My listings"><img src="media/forsale-enquiries.webp" alt="Enquiries on My listings" loading="lazy"></button><figcaption>Enquiries on My listings</figcaption></figure><ul><li><b>Reply</b> opens a chat with the buyer.</li><li><b>Share documents and my name</b> shares your documents with that buyer only.</li></ul><p>We also email you each time a buyer gets in touch.</p><h3>Update your listing</h3><p>On <b>My listings</b> you can:</p><ul><li><b>Edit</b> the listing at any time.</li><li><b>Mark as under offer</b> when you’ve accepted an offer. Buyers can still see and save it.</li><li><b>Pause</b> it to hide it from buyers for a while.</li><li><b>Mark as sold</b> when the sale closes. The listing is then hidden from buyers.</li></ul>$h$, 46, '2026-11-27') on conflict (id) do update set topic = excluded.topic, title = excluded.title, summary = excluded.summary, tags = excluded.tags, popular = excluded.popular, html = excluded.html, position = excluded.position, updated_on = excluded.updated_on;
insert into help_articles (id, topic, title, summary, tags, popular, html, position, updated_on) values ($h$business-images$h$, $h$business$h$, $h$Business logo and header sizes$h$, $h$The best image sizes for your business page.$h$, $h$logo cover image size$h$, false, $h$<div class="tw"><table><thead><tr><th>Image</th><th>Best size</th><th>Where it shows</th></tr></thead><tbody><tr><td>Logo</td><td>400 × 400 pixels, square</td><td>On your page, cards, posts and messages</td></tr><tr><td>Header</td><td>1584 × 396 pixels (4 to 1)</td><td>Across the top of your page, on directory cards and when your link is shared</td></tr></tbody></table></div><div class="call tip"><b>Tip</b><span>The header is trimmed more on phones. Keep the important part of the picture in the middle.</span></div>$h$, 47, '2026-11-27') on conflict (id) do update set topic = excluded.topic, title = excluded.title, summary = excluded.summary, tags = excluded.tags, popular = excluded.popular, html = excluded.html, position = excluded.position, updated_on = excluded.updated_on;
insert into help_articles (id, topic, title, summary, tags, popular, html, position, updated_on) values ($h$ask-hub-ai$h$, $h$ai$h$, $h$Ask the Hub AI$h$, $h$Get quick answers to small-business questions.$h$, $h$ai assistant chatbot questions$h$, true, $h$<figure class="fig vid"><div class="vbox"><video src="media/vid-ask.mp4" poster="media/vid-ask.jpg" muted loop playsinline preload="none" aria-label="Video walkthrough: Asking the Hub AI a question"></video><button type="button" class="vplay" aria-label="Play walkthrough">&#9654;</button></div><figcaption><span class="vtag">Walkthrough</span>Asking the Hub AI a question</figcaption></figure><ol class="steps"><li>Open <b>Explore</b>, then <b>Ask the Hub AI</b> (or use the box on your Home page).</li><li>Type your question in plain language, for example "How do I register for HST in Ontario?"</li><li>The answer links to related articles, groups and members who can help.</li></ol><div class="call plan"><b>Plans</b><span>Free: 10 AI questions a month. Plus and Advisor: 100 a month, plus help with grant applications.</span></div><div class="call note"><b>Good to know</b><span>AI can make mistakes. For tax, legal or financial decisions, check with a professional. You can find one on the SME Advisors page.</span></div><figure class="fig"><button type="button" class="zoom" data-zoom="media/ai-ask.webp" aria-label="Enlarge screenshot: Ask the Hub"><img src="media/ai-ask.webp" alt="Ask the Hub" loading="lazy"></button><figcaption>Ask the Hub</figcaption></figure>$h$, 48, '2026-11-27') on conflict (id) do update set topic = excluded.topic, title = excluded.title, summary = excluded.summary, tags = excluded.tags, popular = excluded.popular, html = excluded.html, position = excluded.position, updated_on = excluded.updated_on;
insert into help_articles (id, topic, title, summary, tags, popular, html, position, updated_on) values ($h$ai-matchmaking$h$, $h$ai$h$, $h$AI matchmaking: meet the right owner$h$, $h$Answer five short questions and get matched with the right people.$h$, $h$match matchmaking meet who$h$, false, $h$<figure class="fig vid"><div class="vbox"><video src="media/vid-match.mp4" poster="media/vid-match.jpg" muted loop playsinline preload="none" aria-label="Video walkthrough: Answering the matchmaking questions and seeing your matches"></video><button type="button" class="vplay" aria-label="Play walkthrough">&#9654;</button></div><figcaption><span class="vtag">Walkthrough</span>Answering the matchmaking questions and seeing your matches</figcaption></figure><ol class="steps"><li>Open <b>Explore</b>, then <b>AI matchmaking</b>, and select <b>Start my 2-minute form</b>.</li><li>Answer five steps: <b>your goal</b>, <b>what you need</b>, <b>who to meet</b>, <b>when you are free</b>, then <b>check and match</b>.</li><li>Select <b>Find my matches</b>.</li><li>Your best match shows a match score, <b>why this match</b>, people you both know and times for a 20-minute call. Pick a time to book.</li><li>Under <b>More good matches</b>, select <b>Accept introduction</b> or <b>Not now</b>.</li></ol><div class="call tip"><b>Tip</b><span>The more specific your "Looking for" tags are on your profile, the better your matches.</span></div>$h$, 49, '2026-11-27') on conflict (id) do update set topic = excluded.topic, title = excluded.title, summary = excluded.summary, tags = excluded.tags, popular = excluded.popular, html = excluded.html, position = excluded.position, updated_on = excluded.updated_on;
insert into help_articles (id, topic, title, summary, tags, popular, html, position, updated_on) values ($h$ai-profile-builder$h$, $h$ai$h$, $h$Write your profile with AI$h$, $h$Let AI draft your introduction from a few answers.$h$, $h$ai write bio introduction$h$, false, $h$<ol class="steps"><li>Open your profile and select <b>Build my profile with AI</b> (or <b>Rewrite with AI</b>).</li><li>Answer a few questions about what you do and who you serve.</li><li>Choose a tone.</li><li>Review the draft, edit anything you like, then save.</li></ol><p>Nothing is published until you save.</p><figure class="fig"><button type="button" class="zoom" data-zoom="media/ai-builder.webp" aria-label="Enlarge screenshot: The AI profile builder"><img src="media/ai-builder.webp" alt="The AI profile builder" loading="lazy"></button><figcaption>The AI profile builder</figcaption></figure>$h$, 50, '2026-11-27') on conflict (id) do update set topic = excluded.topic, title = excluded.title, summary = excluded.summary, tags = excluded.tags, popular = excluded.popular, html = excluded.html, position = excluded.position, updated_on = excluded.updated_on;
insert into help_articles (id, topic, title, summary, tags, popular, html, position, updated_on) values ($h$ai-limits$h$, $h$ai$h$, $h$How AI on SME Hub uses your information$h$, $h$What the AI tools can see, and how limits work.$h$, $h$ai privacy limits data$h$, false, $h$<ul><li>AI answers use SME Hub content, such as articles, public posts and member profiles, to point you to useful people and resources.</li><li>Monthly AI limits depend on your plan and reset at the start of each month. See <a href="#/a/plans-compared">Free, Plus and Advisor plans compared</a>.</li></ul>$h$, 51, '2026-11-27') on conflict (id) do update set topic = excluded.topic, title = excluded.title, summary = excluded.summary, tags = excluded.tags, popular = excluded.popular, html = excluded.html, position = excluded.position, updated_on = excluded.updated_on;
insert into help_articles (id, topic, title, summary, tags, popular, html, position, updated_on) values ($h$write-blog$h$, $h$blogs$h$, $h$Write a member blog post$h$, $h$Share longer advice and stories with the community.$h$, $h$blog article write publish$h$, false, $h$<figure class="fig"><button type="button" class="zoom" data-zoom="media/blog-list.webp" aria-label="Enlarge screenshot: Member blogs"><img src="media/blog-list.webp" alt="Member blogs" loading="lazy"></button><figcaption>Member blogs</figcaption></figure><ol class="steps"><li>Open <b>Explore</b>, then <b>Member blogs</b>, and select <b>Write</b>.</li><li>Add a title and a cover image (required).</li><li>Build your article with headings, paragraphs, lists, quotes and images. Your draft saves automatically.</li><li>Choose a category and add tags.</li><li>Select <b>Publish</b>.</li></ol><div class="call plan"><b>Plans</b><span>Blog posts by Free members are reviewed by the Hub team before they go live. Plus and Advisor members publish straight away.</span></div><p>Categories: Money, Sales and marketing, Operations, Hiring and people, AI and technology, Legal, and Owner stories.</p><figure class="fig"><button type="button" class="zoom" data-zoom="media/blog-write.webp" aria-label="Enlarge screenshot: Writing a member blog post"><img src="media/blog-write.webp" alt="Writing a member blog post" loading="lazy"></button><figcaption>Writing a member blog post</figcaption></figure>$h$, 52, '2026-11-27') on conflict (id) do update set topic = excluded.topic, title = excluded.title, summary = excluded.summary, tags = excluded.tags, popular = excluded.popular, html = excluded.html, position = excluded.position, updated_on = excluded.updated_on;
insert into help_articles (id, topic, title, summary, tags, popular, html, position, updated_on) values ($h$hashtags$h$, $h$blogs$h$, $h$Use and follow hashtags$h$, $h$Tag topics in posts and follow the ones you care about.$h$, $h$hashtag tag topic follow trending$h$, false, $h$<p>Type <b>#</b> followed by a word in a post, comment or blog, for example #cashflow or #hiring. Hashtags become links to a page with every post on that topic.</p><ul><li>Open <b>Explore</b>, then <b>Hashtags</b>, to see trending topics.</li><li>Select <b>Follow</b> on a hashtag page to see those posts in your feed.</li></ul><div class="call note"><b>Good to know</b><span>A hashtag must be 3 to 24 characters long, and you can use up to 5 in a post. Some spammy words are blocked.</span></div><figure class="fig"><button type="button" class="zoom" data-zoom="media/tags.webp" aria-label="Enlarge screenshot: The Hashtags page"><img src="media/tags.webp" alt="The Hashtags page" loading="lazy"></button><figcaption>The Hashtags page</figcaption></figure>$h$, 53, '2026-11-27') on conflict (id) do update set topic = excluded.topic, title = excluded.title, summary = excluded.summary, tags = excluded.tags, popular = excluded.popular, html = excluded.html, position = excluded.position, updated_on = excluded.updated_on;
insert into help_articles (id, topic, title, summary, tags, popular, html, position, updated_on) values ($h$events$h$, $h$explore$h$, $h$Find, save and host events$h$, $h$Search events, save them with reminders and add them to your calendar. SME Advisors can host their own.$h$, $h$events webinar workshop rsvp register save reminder calendar host zoom ticket green room$h$, false, $h$<p>Open <b>Explore</b>, then <b>Events</b>, to see upcoming online and in-person events from CanadianSME, the SME Hub team and members.</p><h3>Find an event</h3><p>Search by topic, host or city, then narrow the list by date, online or in person, type, topic, province, host, or <b>Free only</b>. Select <b>Clear filters</b> to start again.</p><h3>Save it or register</h3><ul><li><b>Save</b> (the bookmark) keeps an event in your <b>Saved</b> tab and turns on reminders.</li><li><b>Register</b> saves your seat. For paid events you pay by card when you register.</li><li>For events without a date yet, select <b>Tell me the date</b> and we email you when it is announced.</li></ul><h3>Reminders and your calendar</h3><p>We remind you 1 day and 1 hour before, by email and in your notifications. Change the timing on the event’s page under <b>Remind me</b>, or turn event reminders off in <b>Settings and privacy</b>, then <b>Notifications</b>. To add an event to your own calendar, open it and select <b>Add to my calendar</b>: Google Calendar, Outlook.com, or a calendar file for Apple Calendar and Outlook.</p><h3>Host your own event</h3><p>SME Advisors can host webinars, workshops and meetups, free or paid. Select <b>Host an event</b>, fill in the details and publish. Your event shows on Hub Events and on your business page right away. Events are for teaching, sharing or bringing owners together; sales pitches belong in offers.</p><h3>Events on Zoom</h3><p>When you register for an event on Zoom, you get a ticket on the event’s page and by email with your own join link. Please don’t forward it. The <b>Join</b> button opens 15 minutes before the start.</p><p>SME Advisors can run their events on their own Zoom account: we create the meeting, send everyone their own link and give the advisor a green room before going live. Advisors can also paste a Teams or Meet link instead. See <a href="#/a/zoom-advisors">Connect Zoom (SME Advisors)</a>.</p><div class="call note"><b>Good to know</b><span>Times show in the event’s own time zone, such as ET or PT.</span></div>$h$, 54, '2026-11-27') on conflict (id) do update set topic = excluded.topic, title = excluded.title, summary = excluded.summary, tags = excluded.tags, popular = excluded.popular, html = excluded.html, position = excluded.position, updated_on = excluded.updated_on;
insert into help_articles (id, topic, title, summary, tags, popular, html, position, updated_on) values ($h$smb-advisors$h$, $h$explore$h$, $h$Book a free consultation with an SME Advisor$h$, $h$Get expert help from accountants, lawyers and other advisors, and book a free 30-minute consultation on Zoom.$h$, $h$advisor expert accountant lawyer book call consultation zoom free calendar$h$, false, $h$<ol class="steps"><li>Open <b>Explore</b>, then <b>SME Advisors</b>.</li><li>Filter by area, such as tax, legal, marketing or food and retail.</li><li>Open an advisor’s profile to see their experience, languages, rating and usual reply time.</li><li>Select <b>Book a free call</b>. The calendar shows the days the advisor is free in blue.</li><li>Pick a day, pick a time, then select <b>Next</b>.</li><li>Check your business name, write a sentence about what you want to talk about, and select <b>Book my free call</b>.</li></ol><figure class="fig"><button type="button" class="zoom" data-zoom="media/consult-book.webp" aria-label="Enlarge screenshot: Picking a time for a free consultation"><img src="media/consult-book.webp" alt="Picking a time for a free consultation" loading="lazy"></button><figcaption>Picking a time for a free consultation</figcaption></figure><h3>What happens next</h3><ul><li>You and the advisor each get an email straight away with the time, your question and the Zoom link.</li><li>The email has a calendar invite for Google Calendar, Outlook or Apple Calendar. You can also select <b>Add to my calendar</b> on the advisor’s profile.</li><li>We remind you a day and an hour before.</li><li>To move or cancel, open the advisor’s profile and select <b>Reschedule</b> or <b>Cancel</b>. The advisor is told by email.</li></ul><div class="call note"><b>Good to know</b><span>Times show in Eastern Time. Consultations are free on every plan. Advisors need at least 12 hours’ notice, and you can book up to 30 days ahead.</span></div>$h$, 55, '2026-11-27') on conflict (id) do update set topic = excluded.topic, title = excluded.title, summary = excluded.summary, tags = excluded.tags, popular = excluded.popular, html = excluded.html, position = excluded.position, updated_on = excluded.updated_on;
insert into help_articles (id, topic, title, summary, tags, popular, html, position, updated_on) values ($h$zoom-advisors$h$, $h$explore$h$, $h$Connect Zoom (SME Advisors)$h$, $h$Link your own Zoom once and use it for your events and free consultations.$h$, $h$zoom advisor connect host event consultation booking calendar green room$h$, false, $h$<p>SME Advisors can link their own Zoom account. After that, SME Hub creates the meetings for you, so you never copy and paste links.</p><h3>Connect Zoom</h3><ol class="steps"><li>Open <b>Settings and privacy</b>, then <b>Connected apps</b>.</li><li>Select <b>Connect my Zoom</b>, read what SME Hub will do, then select <b>Continue to Zoom</b>.</li><li>Sign in to Zoom and allow access. You come straight back to SME Hub.</li></ol><figure class="fig"><button type="button" class="zoom" data-zoom="media/zoom-connect.webp" aria-label="Enlarge screenshot: What SME Hub will do in your Zoom"><img src="media/zoom-connect.webp" alt="What SME Hub will do in your Zoom" loading="lazy"></button><figcaption>What SME Hub will do in your Zoom</figcaption></figure><p>SME Hub only creates and changes the meetings you set up here. It never sees your other meetings, recordings or contacts. You can disconnect any time in <b>Connected apps</b>.</p><h3>Host an event on your Zoom</h3><ol class="steps"><li>Select <b>Host an event</b> and choose <b>Online</b>.</li><li>Under <b>How will people join?</b>, choose <b>My Zoom account</b>.</li><li>Turn the waiting room, registered-only and cloud recording on or off, then publish.</li></ol><p>Everyone who registers gets their own join link by email and on the event’s page, and you get an email for each sign-up (or a daily summary). On the day, open your event and select <b>Open the green room</b> to check your camera, send a quick note to everyone and go live. After the event, the wrap-up shows who came and who to follow up with.</p><div class="call tip"><b>Heads-up</b><span>Free Zoom accounts end meetings at 40 minutes. If your event is longer, check your Zoom plan.</span></div><h3>Free consultations</h3><ol class="steps"><li>Open <b>Settings and privacy</b>, then <b>Free consultations</b>.</li><li>Choose how long each call is and the mornings or afternoons you are free.</li><li>Set your rules: the gap between calls, the most calls a day, how far ahead members can book and the shortest notice.</li><li>Choose which questions members must answer.</li></ol><figure class="fig"><button type="button" class="zoom" data-zoom="media/zoom-consult-settings.webp" aria-label="Enlarge screenshot: Free consultation settings"><img src="media/zoom-consult-settings.webp" alt="Free consultation settings" loading="lazy"></button><figcaption>Free consultation settings</figcaption></figure><p>Members book from your profile. You both get an email with the time, their question, the Zoom link and a calendar invite. The booking also appears in <b>My leads</b>. If you connect Google Calendar, times you are already busy are hidden automatically.</p><div class="call note"><b>Good to know</b><span>Hosting events, connecting Zoom and free consultations are part of the Advisor plan.</span></div>$h$, 56, '2026-11-27') on conflict (id) do update set topic = excluded.topic, title = excluded.title, summary = excluded.summary, tags = excluded.tags, popular = excluded.popular, html = excluded.html, position = excluded.position, updated_on = excluded.updated_on;
insert into help_articles (id, topic, title, summary, tags, popular, html, position, updated_on) values ($h$my-deadlines$h$, $h$explore$h$, $h$Track your tax deadlines with My deadlines$h$, $h$Get your GST/HST, payroll and income tax dates for the year, with reminders before each one.$h$, $h$deadlines tax gst hst payroll remittance cra income tax instalments reminders calendar t4$h$, false, $h$<p>My deadlines turns a few answers about your business into your CRA dates for the next 12 months. It’s free for every member, and only you can see it.</p><h3>Set it up</h3><ol class="steps"><li>Open the <b>Me</b> menu or <b>Explore</b>, then <b>My deadlines</b>.</li><li>Answer five questions: your province, how the business is set up, how often you file GST/HST, whether you have employees, and whether you pay tax by instalments.</li><li>Watch <b>Your calendar so far</b> on the right update as you answer, then select <b>Create my deadlines</b>.</li></ol><figure class="fig"><button type="button" class="zoom" data-zoom="media/deadlines-setup.webp" aria-label="Enlarge screenshot: The five setup questions with a live preview"><img src="media/deadlines-setup.webp" alt="The five setup questions with a live preview" loading="lazy"></button><figcaption>The five setup questions with a live preview</figcaption></figure><h3>Use the page</h3><ul><li>The top row shows anything <b>overdue</b>, what’s due in the next 30 days and your reminder settings.</li><li><b>Next up</b> shows your next date, how many days are left and three simple steps for how to do it.</li><li>Switch between <b>List</b> and <b>Year at a glance</b>, or filter by sales tax, payroll, income tax or your own dates.</li><li>Select any date to see what it’s for and how to file or pay it.</li><li>Tick the box once it’s done. If a date passes and isn’t ticked, it moves to the red <b>overdue</b> box at the top.</li></ul><figure class="fig"><button type="button" class="zoom" data-zoom="media/deadlines-page.webp" aria-label="Enlarge screenshot: My deadlines, with the next date and the list"><img src="media/deadlines-page.webp" alt="My deadlines, with the next date and the list" loading="lazy"></button><figcaption>My deadlines, with the next date and the list</figcaption></figure><h3>Add your own dates</h3><p>Select <b>Add a deadline</b> for things like a business licence, an insurance renewal or a WSIB or WCB report. They can repeat every month, every 3 months or every year.</p><h3>Reminders and your calendar</h3><ul><li>Choose email, the bell or both, and remind me 14, 7 or 1 day before.</li><li>Turn on <b>Monday summary</b> to see the week’s dates in your Monday email.</li><li>Select <b>Add all to my calendar</b> to download your dates for Google, Outlook or Apple Calendar, with the same reminders. You can also add one date at a time.</li></ul><div class="call note"><b>Good to know</b><span>Dates follow the CRA’s general rules for your answers. If a date falls on a weekend we show the next business day. Your CRA account always shows your exact dates. This isn’t tax advice, so check with your accountant if you’re unsure.</span></div>$h$, 57, '2026-11-27') on conflict (id) do update set topic = excluded.topic, title = excluded.title, summary = excluded.summary, tags = excluded.tags, popular = excluded.popular, html = excluded.html, position = excluded.position, updated_on = excluded.updated_on;
insert into help_articles (id, topic, title, summary, tags, popular, html, position, updated_on) values ($h$become-advisor$h$, $h$explore$h$, $h$Become an SME Advisor$h$, $h$For accountants, lawyers, consultants and coaches who serve small businesses.$h$, $h$advisor plan expert badge$h$, false, $h$<p>The <b>Advisor plan</b> ($1,990 a year) includes:</p><ul><li>The SME Advisor badge on your profile and posts</li><li>A place on the Advisors page and in the feed</li><li>Free consultations booked by members, on your own Zoom</li><li>4 offers a month and up to 3 private groups (for example a client circle)</li><li>Hosting events on your own Zoom and selling courses</li><li>One podcast interview and one advertorial a year</li><li>AI leads: members asking about your specialty</li></ul><p>Go to <b>Upgrade plan</b> and choose <b>Advisor</b>.</p>$h$, 58, '2026-11-27') on conflict (id) do update set topic = excluded.topic, title = excluded.title, summary = excluded.summary, tags = excluded.tags, popular = excluded.popular, html = excluded.html, position = excluded.position, updated_on = excluded.updated_on;
insert into help_articles (id, topic, title, summary, tags, popular, html, position, updated_on) values ($h$pavilion$h$, $h$explore$h$, $h$The Made in Canada Pavilion$h$, $h$Discover Canadian manufacturers, services and software, or list your own.$h$, $h$made in canada pavilion manufacturers$h$, true, $h$<p>The Pavilion showcases Canadian businesses in three sections: <b>Manufacturers and makers</b>, <b>Canadian-owned services</b> and <b>Software and AI tools</b>.</p><p>Each listing can show claims about where it is made. These follow common Canadian definitions:</p><div class="tw"><table><thead><tr><th>Claim</th><th>What it means</th></tr></thead><tbody><tr><td>Product of Canada</td><td>At least 98% of the direct cost of making it was spent in Canada</td></tr><tr><td>Made in Canada</td><td>At least 51% of the direct cost was spent in Canada, and the last major production step happened here</td></tr><tr><td>Assembled in Canada</td><td>Put together in Canada, mostly from imported parts</td></tr><tr><td>Canadian-owned</td><td>The business is majority owned by Canadians</td></tr><tr><td>Built in Canada</td><td>The software was designed and developed by a team in Canada</td></tr><tr><td>Data stored in Canada</td><td>Customer data is kept on servers in Canada</td></tr></tbody></table></div><p>Select <b>Request an introduction</b> on a listing, or <b>List your product</b> to add your own.</p><figure class="fig"><button type="button" class="zoom" data-zoom="media/pavilion.webp" aria-label="Enlarge screenshot: The Made in Canada Pavilion"><img src="media/pavilion.webp" alt="The Made in Canada Pavilion" loading="lazy"></button><figcaption>The Made in Canada Pavilion</figcaption></figure>$h$, 59, '2026-11-27') on conflict (id) do update set topic = excluded.topic, title = excluded.title, summary = excluded.summary, tags = excluded.tags, popular = excluded.popular, html = excluded.html, position = excluded.position, updated_on = excluded.updated_on;
insert into help_articles (id, topic, title, summary, tags, popular, html, position, updated_on) values ($h$resources$h$, $h$explore$h$, $h$Resource centres and provincial guides$h$, $h$Guides for every province and resource centres for underrepresented founders.$h$, $h$guides provinces resources indigenous women black immigrant$h$, false, $h$<p>Open <b>About</b> to find:</p><ul><li><b>Provincial business guides:</b> registering, taxes and support programs in each province and territory.</li><li><b>Resource centres:</b> Indigenous, Black, Women, Immigrant and LGBTQ+ Entrepreneurs Resource Centres from CanadianSME.</li><li><b>CanadianSME content:</b> the blog, news, the Small Business Podcast and the magazine.</li></ul><figure class="fig"><button type="button" class="zoom" data-zoom="media/guides.webp" aria-label="Enlarge screenshot: Provincial business guides"><img src="media/guides.webp" alt="Provincial business guides" loading="lazy"></button><figcaption>Provincial business guides</figcaption></figure>$h$, 60, '2026-11-27') on conflict (id) do update set topic = excluded.topic, title = excluded.title, summary = excluded.summary, tags = excluded.tags, popular = excluded.popular, html = excluded.html, position = excluded.position, updated_on = excluded.updated_on;
insert into help_articles (id, topic, title, summary, tags, popular, html, position, updated_on) values ($h$courses-find$h$, $h$courses$h$, $h$Find and enrol in a course$h$, $h$Browse short courses, enrol free or buy a paid course.$h$, $h$courses learn enrol enroll buy paid free catalogue training$h$, true, $h$<figure class="fig vid"><div class="vbox"><video src="media/vid-course.mp4" poster="media/vid-course.jpg" muted loop playsinline preload="none" aria-label="Video walkthrough: Finding a course, enrolling and finishing your first lesson"></video><button type="button" class="vplay" aria-label="Play walkthrough">&#9654;</button></div><figcaption><span class="vtag">Walkthrough</span>Finding a course, enrolling and finishing your first lesson</figcaption></figure><ol class="steps"><li>Open <b>Explore</b>, then <b>Courses</b>.</li><li>Search by title, topic or instructor, or pick a topic. Use <b>Filters</b> for level, language, and free or paid.</li><li>Hover over a course (or tap the <b>i</b> button on a phone) for a quick look, or open it to see the full course page.</li><li>On the course page, select <b>Enrol for free</b>. For a paid course, select <b>Buy course</b> and pay once. You keep access for good.</li><li>Your first lesson opens straight away.</li></ol><figure class="fig"><button type="button" class="zoom" data-zoom="media/course-browse.webp" aria-label="Enlarge screenshot: Courses: search, topics and filters"><img src="media/course-browse.webp" alt="Courses: search, topics and filters" loading="lazy"></button><figcaption>Courses: search, topics and filters</figcaption></figure><h3>What’s on a course page</h3><p>The course page shows who it’s for, what you’ll be able to do, what you need before you start, every section and lesson, the instructors, reviews and classmates.</p><figure class="fig"><button type="button" class="zoom" data-zoom="media/course-page.webp" aria-label="Enlarge screenshot: A course page, with your progress once you’re enrolled"><img src="media/course-page.webp" alt="A course page, with your progress once you’re enrolled" loading="lazy"></button><figcaption>A course page, with your progress once you’re enrolled</figcaption></figure><figure class="fig"><button type="button" class="zoom" data-zoom="media/course-buy.webp" aria-label="Enlarge screenshot: Buying a paid course. Prices are in Canadian dollars, plus tax for your province."><img src="media/course-buy.webp" alt="Buying a paid course. Prices are in Canadian dollars, plus tax for your province." loading="lazy"></button><figcaption>Buying a paid course. Prices are in Canadian dollars, plus tax for your province.</figcaption></figure><div class="call tip"><b>Tip</b><span>Select the <b>bookmark</b> on any course to save it for later. Saved courses are under <b>Courses</b>, then <b>Saved</b>, on every device you sign in on.</span></div><div class="call note"><b>Good to know</b><span>Many courses have a <b>Free preview</b> lesson that anyone can watch before enrolling.</span></div>$h$, 61, '2026-11-27') on conflict (id) do update set topic = excluded.topic, title = excluded.title, summary = excluded.summary, tags = excluded.tags, popular = excluded.popular, html = excluded.html, position = excluded.position, updated_on = excluded.updated_on;
insert into help_articles (id, topic, title, summary, tags, popular, html, position, updated_on) values ($h$courses-learn$h$, $h$courses$h$, $h$Take lessons and track your progress$h$, $h$Videos, readings, downloads, and picking up where you left off.$h$, $h$lesson video captions speed progress resume locked downloads$h$, true, $h$<ol class="steps"><li>Open <b>Courses</b>, then <b>My learning</b>, and select <b>Continue learning</b>. You go straight to the next lesson you haven’t finished.</li><li>Watch the video or read the lesson. Change the <b>speed</b>, turn <b>captions</b> on or off, or watch <b>full screen</b>.</li><li>When you finish a reading, select <b>Mark complete and continue</b>. A video is marked complete when you watch it to the end.</li><li>Use <b>Course outline</b> to jump between lessons. On a phone, it opens from the button at the top.</li></ol><figure class="fig"><button type="button" class="zoom" data-zoom="media/course-lesson.webp" aria-label="Enlarge screenshot: A lesson, with the course outline on the left"><img src="media/course-lesson.webp" alt="A lesson, with the course outline on the left" loading="lazy"></button><figcaption>A lesson, with the course outline on the left</figcaption></figure><figure class="fig"><button type="button" class="zoom" data-zoom="media/course-content.webp" aria-label="Enlarge screenshot: Lessons show Done, Locked or Opens on a date"><img src="media/course-content.webp" alt="Lessons show Done, Locked or Opens on a date" loading="lazy"></button><figcaption>Lessons show Done, Locked or Opens on a date</figcaption></figure><h3>Pick up on any device</h3><p>Your place is saved to your account, including where you stopped in a video. Start on your phone and finish on your computer.</p><h3>Why is a lesson locked?</h3><ul><li><b>Locked:</b> the course opens lessons in order. Finish the lesson before it.</li><li><b>Opens on a date:</b> the instructor releases it a few days after you enrol, so you have time to practise.</li><li><b>Enrol to unlock</b> or <b>Buy to unlock:</b> you haven’t enrolled yet.</li></ul><h3>Downloads</h3><p>Worksheets and templates are under <b>Downloads</b> in the lesson. Only enrolled learners can download them.</p><figure class="fig"><button type="button" class="zoom" data-zoom="media/course-mylearning.webp" aria-label="Enlarge screenshot: My learning: continue, in progress and completed courses"><img src="media/course-mylearning.webp" alt="My learning: continue, in progress and completed courses" loading="lazy"></button><figcaption>My learning: continue, in progress and completed courses</figcaption></figure>$h$, 62, '2026-11-27') on conflict (id) do update set topic = excluded.topic, title = excluded.title, summary = excluded.summary, tags = excluded.tags, popular = excluded.popular, html = excluded.html, position = excluded.position, updated_on = excluded.updated_on;
insert into help_articles (id, topic, title, summary, tags, popular, html, position, updated_on) values ($h$courses-assignments$h$, $h$courses$h$, $h$Assignments and quizzes$h$, $h$Submit your work, get feedback, and pass the quiz.$h$, $h$assignment homework submit feedback grade quiz test attempts timer$h$, false, $h$<h3>Assignments</h3><ol class="steps"><li>Read <b>The brief</b>. It shows the deadline (with the time zone), the marks and the pass mark.</li><li>Upload your file, paste your answer, or both. Files can be up to 10 MB.</li><li>Select <b>Submit assignment</b>. Only you and the course team can see it.</li><li>You can change your submission until it’s graded. We email you when feedback is ready.</li></ol><figure class="fig"><button type="button" class="zoom" data-zoom="media/course-assignment.webp" aria-label="Enlarge screenshot: An assignment: the brief, how it’s marked, and your submission"><img src="media/course-assignment.webp" alt="An assignment: the brief, how it’s marked, and your submission" loading="lazy"></button><figcaption>An assignment: the brief, how it’s marked, and your submission</figcaption></figure><h3>Quizzes</h3><ol class="steps"><li>Select <b>Start quiz</b>. If there’s a time limit, the timer starts now.</li><li>Your answers save as you go. If you refresh or switch devices, you come back to the same attempt.</li><li>Select <b>Submit answers</b> to see your score and which questions to review.</li><li>If you don’t pass, select <b>Try again</b>. The number of attempts is shown before you start.</li></ol><figure class="fig"><button type="button" class="zoom" data-zoom="media/course-quiz.webp" aria-label="Enlarge screenshot: A quiz in progress, with the time left"><img src="media/course-quiz.webp" alt="A quiz in progress, with the time left" loading="lazy"></button><figcaption>A quiz in progress, with the time left</figcaption></figure><div class="call note"><b>Good to know</b><span>If the time runs out, your answers are submitted automatically.</span></div>$h$, 63, '2026-11-27') on conflict (id) do update set topic = excluded.topic, title = excluded.title, summary = excluded.summary, tags = excluded.tags, popular = excluded.popular, html = excluded.html, position = excluded.position, updated_on = excluded.updated_on;
insert into help_articles (id, topic, title, summary, tags, popular, html, position, updated_on) values ($h$courses-reviews$h$, $h$courses$h$, $h$Reviews, classmates and finishing a course$h$, $h$Leave a review, see who else is learning, and control your privacy.$h$, $h$review rating classmates privacy complete certificate discussion$h$, false, $h$<h3>Finish a course</h3><p>A course is complete when every lesson is done: readings and videos, the quiz passed, and the assignment submitted (or passed, if the course asks for that). We email you to say well done.</p><h3>Leave a review</h3><p>Once you’ve finished at least one lesson, select <b>Write a review</b> on the course page. Choose 1 to 5 stars and say what helped. You can edit or delete it any time.</p><figure class="fig"><button type="button" class="zoom" data-zoom="media/course-review.webp" aria-label="Enlarge screenshot: Writing a review"><img src="media/course-review.webp" alt="Writing a review" loading="lazy"></button><figcaption>Writing a review</figcaption></figure><h3>Classmates</h3><p>The course page shows members who recently enrolled. They see your name and photo too. Your progress, grades and work are never shown to them.</p><p>To hide yourself, go to <b>Courses</b>, then <b>My learning</b>, and turn off <b>Show me as a classmate</b>.</p><h3>Course discussion</h3><p>Many courses link to a group where you can ask questions and swap notes. Select <b>Open course discussion</b> on the course page.</p>$h$, 64, '2026-11-27') on conflict (id) do update set topic = excluded.topic, title = excluded.title, summary = excluded.summary, tags = excluded.tags, popular = excluded.popular, html = excluded.html, position = excluded.position, updated_on = excluded.updated_on;
insert into help_articles (id, topic, title, summary, tags, popular, html, position, updated_on) values ($h$courses-teach$h$, $h$courses$h$, $h$For instructors: edit your course and grade work$h$, $h$The Teaching page, the course editor and publishing.$h$, $h$instructor teach teaching grade grading editor create course publish advisor$h$, false, $h$<p>SME Advisors and guest experts can teach courses. The CanadianSME team sets up the course and adds you as an instructor.</p><h3>Grade assignments</h3><ol class="steps"><li>Open <b>Courses</b>, then <b>Teaching</b>. A red number shows how many submissions are waiting.</li><li>Under <b>To grade</b>, select <b>Grade</b> next to a learner.</li><li>Read their work, enter the marks and write feedback, then select <b>Send grade and feedback</b>. They get an email straight away.</li></ol><figure class="fig"><button type="button" class="zoom" data-zoom="media/course-grading.webp" aria-label="Enlarge screenshot: Grading an assignment on the Teaching page"><img src="media/course-grading.webp" alt="Grading an assignment on the Teaching page" loading="lazy"></button><figcaption>Grading an assignment on the Teaching page</figcaption></figure><h3>Edit your course</h3><p>Select <b>Edit course</b>. The editor has five tabs:</p><ul><li><b>Details:</b> title, summary, description, who it’s for, cover image and preview video.</li><li><b>Content:</b> sections and lessons. Add video, reading, assignment or quiz lessons, change the order with the arrows, upload videos and captions, add downloads and write quiz questions.</li><li><b>Access and rules:</b> free or paid, lessons in order or any order, and when an assignment counts as complete.</li><li><b>Instructors:</b> who teaches the course.</li><li><b>Publish:</b> a checklist, then <b>Ask the Hub team to publish</b>.</li></ul><figure class="fig"><button type="button" class="zoom" data-zoom="media/course-editor.webp" aria-label="Enlarge screenshot: The Content tab of the course editor"><img src="media/course-editor.webp" alt="The Content tab of the course editor" loading="lazy"></button><figcaption>The Content tab of the course editor</figcaption></figure><div class="call tip"><b>Tip</b><span>Use <b>Preview as a learner</b> to see the course exactly as a new learner does. Nothing you do in preview is saved.</span></div><div class="call note"><b>Good to know</b><span>Changes to a published course go live as soon as you make them. Only the Hub team can publish or unpublish a course.</span></div>$h$, 65, '2026-11-27') on conflict (id) do update set topic = excluded.topic, title = excluded.title, summary = excluded.summary, tags = excluded.tags, popular = excluded.popular, html = excluded.html, position = excluded.position, updated_on = excluded.updated_on;
insert into help_articles (id, topic, title, summary, tags, popular, html, position, updated_on) values ($h$plans-compared$h$, $h$plans$h$, $h$Free, Plus and Advisor plans compared$h$, $h$What each plan includes.$h$, $h$price pricing plan plus advisor free compare$h$, true, $h$<p>Prices are in Canadian dollars, before HST.</p><figure class="fig"><button type="button" class="zoom" data-zoom="media/plans.webp" aria-label="Enlarge screenshot: The Membership plans page"><img src="media/plans.webp" alt="The Membership plans page" loading="lazy"></button><figcaption>The Membership plans page</figcaption></figure><div class="tw"><table><thead><tr><th>Plan</th><th>Price</th><th>Includes</th></tr></thead><tbody><tr><td>Free</td><td>$0, no card needed</td><td>Profile, connections and messages · one business page · join any group and read every article · post questions, wins, jobs and introductions · blog posts (reviewed before they go live) · 3 people to meet every day and warm introductions · 10 AI questions a month</td></tr><tr><td>Plus</td><td>$19 a month, or $190 a year (2 months free)</td><td>Everything in Free, plus a featured company listing shown first and up to 3 business pages · 2 offers a month · list a business for sale · host 1 private group · blog posts go live straight away · shown more often in suggestions · 100 AI questions a month plus grant application help · discounts on CanadianSME events · see everyone who viewed your profile</td></tr><tr><td>Advisor</td><td>$1,990 a year</td><td>Everything in Plus, plus the SME Advisor badge · a place on the Advisors page · members book free consultations on your own Zoom · 4 offers a month · host 3 private groups · host events on your own Zoom and sell courses · one podcast interview and one advertorial a year · AI leads</td></tr></tbody></table></div>$h$, 66, '2026-11-27') on conflict (id) do update set topic = excluded.topic, title = excluded.title, summary = excluded.summary, tags = excluded.tags, popular = excluded.popular, html = excluded.html, position = excluded.position, updated_on = excluded.updated_on;
insert into help_articles (id, topic, title, summary, tags, popular, html, position, updated_on) values ($h$upgrade$h$, $h$plans$h$, $h$Upgrade, change or cancel your plan$h$, $h$Move up, move down or cancel at any time.$h$, $h$upgrade downgrade cancel billing payment receipts invoice hst billing details$h$, false, $h$<h3>Upgrade</h3><ol class="steps"><li>Select <b>Upgrade plan</b> at the top of any page.</li><li>Choose monthly or yearly, then select <b>Upgrade to Plus</b> or choose <b>Advisor</b>.</li><li>Complete checkout.</li></ol><h3>Change or cancel</h3><ol class="steps"><li>Go to <b>Me</b>, then <b>Settings and privacy</b>, then <b>Plan and billing</b>.</li><li>Select <b>Change plan</b>, <b>Switch to yearly</b> or <b>Cancel plan</b>.</li></ol><p>You can move up, move down or cancel at any time. If you cancel, you keep your paid plan until the end of the period you paid for, then go back to the Free plan. Nothing is deleted: extra business pages and private groups are hidden until you upgrade again.</p><h3>Receipts and billing details</h3><p>Every receipt is on the <b>Plan and billing</b> page as a PDF, with HST shown. Add your business name, address and GST/HST number under <b>Billing details</b> so they appear on future receipts.</p><p>Questions about billing? Email billing@smehub.ca.</p>$h$, 67, '2026-11-27') on conflict (id) do update set topic = excluded.topic, title = excluded.title, summary = excluded.summary, tags = excluded.tags, popular = excluded.popular, html = excluded.html, position = excluded.position, updated_on = excluded.updated_on;
insert into help_articles (id, topic, title, summary, tags, popular, html, position, updated_on) values ($h$founding-offer$h$, $h$plans$h$, $h$Founding Member offer$h$, $h$Plus for $99 in your first year.$h$, $h$discount founding offer$h$, false, $h$<p>The first 250 members who upgrade get <b>Plus for $99 in their first year</b>, then the regular price. The Founding Member badge stays on your profile.</p>$h$, 68, '2026-11-27') on conflict (id) do update set topic = excluded.topic, title = excluded.title, summary = excluded.summary, tags = excluded.tags, popular = excluded.popular, html = excluded.html, position = excluded.position, updated_on = excluded.updated_on;
insert into help_articles (id, topic, title, summary, tags, popular, html, position, updated_on) values ($h$is-free-free$h$, $h$plans$h$, $h$Is the Free plan really free?$h$, $h$Yes, for as long as you like.$h$, $h$free trial card$h$, false, $h$<p>Yes. There is no trial period, no card and no limit on connections. You can stay on Free for as long as you like.</p>$h$, 69, '2026-11-27') on conflict (id) do update set topic = excluded.topic, title = excluded.title, summary = excluded.summary, tags = excluded.tags, popular = excluded.popular, html = excluded.html, position = excluded.position, updated_on = excluded.updated_on;
insert into help_articles (id, topic, title, summary, tags, popular, html, position, updated_on) values ($h$partner-plans$h$, $h$plans$h$, $h$Partner plans for companies that sell to small businesses$h$, $h$Sponsorship and exposure for brands.$h$, $h$sponsor partner advertise brand$h$, false, $h$<p>Companies that sell to small businesses can become SME Hub partners. Partner plans start at $5,000 a year and include event and magazine exposure with CanadianSME. Contact the team at info@canadiansme.ca.</p>$h$, 70, '2026-11-27') on conflict (id) do update set topic = excluded.topic, title = excluded.title, summary = excluded.summary, tags = excluded.tags, popular = excluded.popular, html = excluded.html, position = excluded.position, updated_on = excluded.updated_on;
insert into help_articles (id, topic, title, summary, tags, popular, html, position, updated_on) values ($h$community-guidelines$h$, $h$safety$h$, $h$Community guidelines$h$, $h$The rules that keep SME Hub useful and respectful.$h$, $h$rules guidelines policy conduct$h$, true, $h$<p>SME Hub works when members treat each other with respect and share what they know. These guidelines apply to posts, comments, groups, messages, stories, blogs and business pages.</p><h3>What we value</h3><ul><li><b>Respect.</b> Disagree with ideas, never attack people.</li><li><b>Collaboration.</b> Share knowledge and contacts generously.</li><li><b>Professionalism.</b> Keep it relevant and free of offensive language.</li><li><b>Integrity.</b> Be honest about who you are and what your business does.</li><li><b>Growth.</b> Stay open to feedback and help others improve.</li></ul><h3>Please don’t</h3><ul><li>Spam, including the same comment pasted across groups or unsolicited sales messages.</li><li>Harass, bully, intimidate or stalk anyone.</li><li>Post hate speech about race, religion, gender, sexual orientation, disability or any similar trait.</li><li>Pretend to be someone else or misstate who you work for.</li><li>Share another person’s personal or confidential information without consent.</li><li>Post personal email addresses or phone numbers. Use messaging instead.</li></ul><p>Read the full guidelines, the Anti-Discrimination Policy and the Terms on the <b>Policies and help</b> pages.</p>$h$, 71, '2026-11-27') on conflict (id) do update set topic = excluded.topic, title = excluded.title, summary = excluded.summary, tags = excluded.tags, popular = excluded.popular, html = excluded.html, position = excluded.position, updated_on = excluded.updated_on;
insert into help_articles (id, topic, title, summary, tags, popular, html, position, updated_on) values ($h$report-content$h$, $h$safety$h$, $h$Report a post, member, business or review$h$, $h$Tell the Hub team about something that breaks the rules.$h$, $h$report flag abuse spam scam$h$, true, $h$<p>You can report posts, comments, photos, stories, groups, blog posts, business pages, reviews and members.</p><figure class="fig vid"><div class="vbox"><video src="media/vid-report.mp4" poster="media/vid-report.jpg" muted loop playsinline preload="none" aria-label="Video walkthrough: Reporting a post"></video><button type="button" class="vplay" aria-label="Play walkthrough">&#9654;</button></div><figcaption><span class="vtag">Walkthrough</span>Reporting a post</figcaption></figure><ol class="steps"><li>Open the <b>…</b> menu on the item, or the <b>flag</b> next to a review.</li><li>Select <b>Report</b>.</li><li>Choose a reason and add a note if it helps.</li><li>Select <b>Send report</b>.</li></ol><h3>Reasons you can choose</h3><div class="tw"><table><thead><tr><th>Reason</th><th>For example</th></tr></thead><tbody><tr><td>Spam or disguised advertising</td><td>Sales pitches posted as questions, wins or comments</td></tr><tr><td>Scam or fraud</td><td>Fake offers, requests for money or deposits</td></tr><tr><td>Harassment</td><td>Bullying, threats or repeated unwanted contact</td></tr><tr><td>Fake business or impersonation</td><td>Pretending to be a person or company they are not</td></tr><tr><td>Misinformation</td><td>Misleading or false information</td></tr><tr><td>Offensive</td><td>Abusive or derogatory content</td></tr><tr><td>Inappropriate</td><td>Content that doesn’t belong in a business community</td></tr><tr><td>Other</td><td>Something else the team should look at</td></tr></tbody></table></div><p>Reports are private. The member is not told who reported them.</p><figure class="fig"><button type="button" class="zoom" data-zoom="media/safety-report.webp" aria-label="Enlarge screenshot: Choose a reason and send your report"><img src="media/safety-report.webp" alt="Choose a reason and send your report" loading="lazy"></button><figcaption>Choose a reason and send your report</figcaption></figure>$h$, 72, '2026-11-27') on conflict (id) do update set topic = excluded.topic, title = excluded.title, summary = excluded.summary, tags = excluded.tags, popular = excluded.popular, html = excluded.html, position = excluded.position, updated_on = excluded.updated_on;
insert into help_articles (id, topic, title, summary, tags, popular, html, position, updated_on) values ($h$after-report$h$, $h$safety$h$, $h$What happens after you report$h$, $h$How the Hub team reviews reports.$h$, $h$moderation review suspended hidden$h$, false, $h$<ul><li>Every report goes to the Hub moderation team.</li><li>If several members report the same thing, it may be <b>hidden automatically</b> while the team reviews it.</li><li>The team can restore it, remove it, warn the member or suspend the account.</li><li>Members who are reported or blocked many times may be suspended automatically until the team reviews their account.</li><li>You get a notification when there is a decision on something you reported.</li></ul>$h$, 73, '2026-11-27') on conflict (id) do update set topic = excluded.topic, title = excluded.title, summary = excluded.summary, tags = excluded.tags, popular = excluded.popular, html = excluded.html, position = excluded.position, updated_on = excluded.updated_on;
insert into help_articles (id, topic, title, summary, tags, popular, html, position, updated_on) values ($h$suspended$h$, $h$safety$h$, $h$My account or post was hidden or suspended$h$, $h$What it means and how to appeal.$h$, $h$appeal suspended hidden removed$h$, false, $h$<p>If your post was hidden or your account was suspended, it is because members reported it or our team found it breaks the community guidelines.</p><p>To ask for a review, email <b>support@smehub.ca</b> with your name and a link to the post or profile. A person on the Hub team will look at it.</p>$h$, 74, '2026-11-27') on conflict (id) do update set topic = excluded.topic, title = excluded.title, summary = excluded.summary, tags = excluded.tags, popular = excluded.popular, html = excluded.html, position = excluded.position, updated_on = excluded.updated_on;
insert into help_articles (id, topic, title, summary, tags, popular, html, position, updated_on) values ($h$scams$h$, $h$safety$h$, $h$Avoid scams$h$, $h$Signs of a scam and how to stay safe.$h$, $h$scam fraud safety phishing$h$, false, $h$<ul><li>Be careful with anyone who asks for a deposit, a gift card or crypto before you have met or signed anything.</li><li>Check the business page, reviews and recommendations before you pay a new supplier.</li><li>Never share passwords or one-time codes. SME Hub staff will never ask for them.</li><li>Report anything suspicious. See <a href="#/a/report-content">Report a post, member, business or review</a>.</li></ul>$h$, 75, '2026-11-27') on conflict (id) do update set topic = excluded.topic, title = excluded.title, summary = excluded.summary, tags = excluded.tags, popular = excluded.popular, html = excluded.html, position = excluded.position, updated_on = excluded.updated_on;
insert into help_articles (id, topic, title, summary, tags, popular, html, position, updated_on) values ($h$log-in$h$, $h$account$h$, $h$Log in, and the code on new devices$h$, $h$How logging in works, and why we sometimes email you a code.$h$, $h$login log in sign in code two-step new device locked$h$, true, $h$<ol class="steps"><li>Select <b>Sign in</b> at the top of any page.</li><li>Enter your email and password, or use <b>Google</b> or <b>LinkedIn</b> if that is how you joined.</li><li>Leave <b>Keep me logged in on this device</b> ticked on your own computer or phone. Untick it on a shared computer.</li></ol><figure class="fig"><button type="button" class="zoom" data-zoom="media/acct-login-error.webp" aria-label="Enlarge screenshot: The log-in page, with the message you see if the password doesn’t match"><img src="media/acct-login-error.webp" alt="The log-in page, with the message you see if the password doesn’t match" loading="lazy"></button><figcaption>The log-in page, with the message you see if the password doesn’t match</figcaption></figure><h3>The 6-digit code on a new device</h3><p>When you log in from a computer, phone or browser we haven’t seen before, we email you a <b>6-digit code</b> to make sure it’s really you. Enter it to finish logging in. The code works for 10 minutes. Tick <b>Trust this device for 30 days</b> so we don’t ask again on that device.</p><figure class="fig"><button type="button" class="zoom" data-zoom="media/acct-login-code.webp" aria-label="Enlarge screenshot: Confirm it’s you with the code from your email"><img src="media/acct-login-code.webp" alt="Confirm it’s you with the code from your email" loading="lazy"></button><figcaption>Confirm it’s you with the code from your email</figcaption></figure><p>We also email you about every sign-in from a new device. If it wasn’t you, change your password straight away. See <a href="#/a/change-password">Change your password and see where you’re logged in</a>.</p><h3>Too many tries</h3><p>After <b>5 wrong passwords in a row</b>, we pause sign-ins to your account for <b>15 minutes</b> and email you. Wait, or reset your password. See <a href="#/a/reset-password">Forgot your password? Reset it</a>.</p>$h$, 76, '2026-11-27') on conflict (id) do update set topic = excluded.topic, title = excluded.title, summary = excluded.summary, tags = excluded.tags, popular = excluded.popular, html = excluded.html, position = excluded.position, updated_on = excluded.updated_on;
insert into help_articles (id, topic, title, summary, tags, popular, html, position, updated_on) values ($h$reset-password$h$, $h$account$h$, $h$Forgot your password? Reset it$h$, $h$Get a reset link by email and choose a new password.$h$, $h$forgot password reset link expired locked out$h$, true, $h$<figure class="fig vid"><div class="vbox"><video src="media/vid-reset.mp4" poster="media/vid-reset.jpg" muted loop playsinline preload="none" aria-label="Video walkthrough: Resetting your password"></video><button type="button" class="vplay" aria-label="Play walkthrough">&#9654;</button></div><figcaption><span class="vtag">Walkthrough</span>Resetting your password</figcaption></figure><ol class="steps"><li>On the log-in page, select <b>Forgot password?</b></li><li>Enter the email you use for SME Hub and select <b>Send reset link</b>.</li><li>Open the email from <b>SME Hub Security (security@smehub.ca)</b> and select <b>Reset my password</b>.</li><li>Type your new password twice and select <b>Save new password</b>.</li></ol><figure class="fig"><button type="button" class="zoom" data-zoom="media/acct-forgot.webp" aria-label="Enlarge screenshot: Check your email for the reset link"><img src="media/acct-forgot.webp" alt="Check your email for the reset link" loading="lazy"></button><figcaption>Check your email for the reset link</figcaption></figure><figure class="fig"><button type="button" class="zoom" data-zoom="media/acct-reset.webp" aria-label="Enlarge screenshot: Choose a new password. The checklist turns green as you go."><img src="media/acct-reset.webp" alt="Choose a new password. The checklist turns green as you go." loading="lazy"></button><figcaption>Choose a new password. The checklist turns green as you go.</figcaption></figure><div class="call tip"><b>Tip</b><span>Keep <b>Log me out on all other devices</b> ticked if you think someone else knows your old password.</span></div><h3>The link has expired</h3><p>Reset links work for <b>60 minutes</b> and only once. If yours has expired or was already used, select <b>Send me a new link</b>.</p><figure class="fig"><button type="button" class="zoom" data-zoom="media/acct-reset-expired.webp" aria-label="Enlarge screenshot: An expired link"><img src="media/acct-reset-expired.webp" alt="An expired link" loading="lazy"></button><figcaption>An expired link</figcaption></figure><h3>The email didn’t arrive</h3><ul><li>Check your spam and promotions folders.</li><li>Make sure you typed the email you joined with. For your privacy we show the same message whether or not an account exists.</li><li>Wait a minute, then select <b>Send the link again</b>.</li><li>Still stuck? Email support@smehub.ca.</li></ul>$h$, 77, '2026-11-27') on conflict (id) do update set topic = excluded.topic, title = excluded.title, summary = excluded.summary, tags = excluded.tags, popular = excluded.popular, html = excluded.html, position = excluded.position, updated_on = excluded.updated_on;
insert into help_articles (id, topic, title, summary, tags, popular, html, position, updated_on) values ($h$change-password$h$, $h$account$h$, $h$Change your password and see where you’re logged in$h$, $h$Change your password while logged in, and log out other devices.$h$, $h$change password security devices sessions log out$h$, false, $h$<ol class="steps"><li>Go to <b>Me</b>, then <b>Settings</b>, then <b>Security and sign-in</b>.</li><li>Under <b>Change your password</b>, enter your current password, then your new password twice.</li><li>Select <b>Update password</b>. We email you to confirm the change.</li></ol><figure class="fig"><button type="button" class="zoom" data-zoom="media/acct-change-password.webp" aria-label="Enlarge screenshot: Security and sign-in"><img src="media/acct-change-password.webp" alt="Security and sign-in" loading="lazy"></button><figcaption>Security and sign-in</figcaption></figure><h3>Where you’re logged in</h3><p>The same page lists every device logged in to your account. Select <b>Log out</b> next to any device you don’t recognise, then change your password.</p><div class="call note"><b>Good to know</b><span>We check new passwords against lists of passwords exposed in other companies’ data breaches, and ask you to pick another if yours is on one.</span></div>$h$, 78, '2026-11-27') on conflict (id) do update set topic = excluded.topic, title = excluded.title, summary = excluded.summary, tags = excluded.tags, popular = excluded.popular, html = excluded.html, position = excluded.position, updated_on = excluded.updated_on;
insert into help_articles (id, topic, title, summary, tags, popular, html, position, updated_on) values ($h$emails-from-us$h$, $h$account$h$, $h$Emails from SME Hub, and how to spot fakes$h$, $h$Which addresses we use, what we send and how to turn emails off.$h$, $h$email spam phishing fake unsubscribe notifications senders$h$, false, $h$<p>We only send email from these addresses. All end in <b>@smehub.ca</b>:</p><div class="tw"><table><thead><tr><th>Address</th><th>What it sends</th></tr></thead><tbody><tr><td>hello@smehub.ca</td><td>Welcome, notifications, digests and event reminders</td></tr><tr><td>security@smehub.ca</td><td>Sign-in codes, password resets and security alerts</td></tr><tr><td>billing@smehub.ca</td><td>Receipts, renewals and payment problems</td></tr><tr><td>business@smehub.ca</td><td>Business page approvals, quote requests and reviews</td></tr><tr><td>community@smehub.ca</td><td>Group and blog approvals, and decisions on reports</td></tr></tbody></table></div><figure class="fig"><button type="button" class="zoom" data-zoom="media/acct-email-example.webp" aria-label="Enlarge screenshot: A real security email from SME Hub"><img src="media/acct-email-example.webp" alt="A real security email from SME Hub" loading="lazy"></button><figcaption>A real security email from SME Hub</figcaption></figure><h3>How to spot a fake</h3><ul><li>We will <b>never</b> ask for your password, a sign-in code or your card number by email, message or phone.</li><li>Our links always go to <b>smehub.ca</b>. Hover over a link (or press and hold on a phone) to check before you select it.</li><li>If something feels wrong, don’t select the link. Go to SME Hub yourself, or forward the email to support@smehub.ca.</li></ul><h3>Turn emails on or off</h3><p>Go to <b>Me</b>, then <b>Settings</b>, then <b>Email notifications</b>, or use the link at the bottom of any notification email. Security, billing and important legal emails are always sent, because they are about your account.</p>$h$, 79, '2026-11-27') on conflict (id) do update set topic = excluded.topic, title = excluded.title, summary = excluded.summary, tags = excluded.tags, popular = excluded.popular, html = excluded.html, position = excluded.position, updated_on = excluded.updated_on;
insert into help_articles (id, topic, title, summary, tags, popular, html, position, updated_on) values ($h$privacy-account$h$, $h$account$h$, $h$Privacy and account settings$h$, $h$Where to manage privacy, your data and your account.$h$, $h$settings privacy data account$h$, false, $h$<p>Go to <b>Me</b>, then <b>Privacy and account</b>. You can:</p><ul><li>Choose who sees each part of your profile. See <a href="#/a/profile-privacy">Choose who sees each part of your profile</a>.</li><li><b>My data:</b> download a copy of your information.</li><li><b>Profile views:</b> browse privately or turn off profile-view tracking. See <a href="#/a/who-viewed">Who viewed my profile</a>.</li><li><b>Close my account.</b> See <a href="#/a/close-account">Close your account</a>.</li></ul><figure class="fig"><button type="button" class="zoom" data-zoom="media/account-page.webp" aria-label="Enlarge screenshot: Privacy and account"><img src="media/account-page.webp" alt="Privacy and account" loading="lazy"></button><figcaption>Privacy and account</figcaption></figure>$h$, 80, '2026-11-27') on conflict (id) do update set topic = excluded.topic, title = excluded.title, summary = excluded.summary, tags = excluded.tags, popular = excluded.popular, html = excluded.html, position = excluded.position, updated_on = excluded.updated_on;
insert into help_articles (id, topic, title, summary, tags, popular, html, position, updated_on) values ($h$download-data$h$, $h$account$h$, $h$Download your data$h$, $h$Get a copy of your profile, posts and activity.$h$, $h$export download data copy$h$, false, $h$<ol class="steps"><li>Go to <b>Me</b>, then <b>Privacy and account</b>.</li><li>Select <b>My data</b>, then <b>Email me my data</b>.</li><li>We prepare a file and email you when it is ready.</li><li>Select <b>Download my data</b> in the email. For your security, the link works for 7 days and only after you log in.</li></ol><p>The file includes your profile, posts, comments, connections, messages, recommendations and business pages.</p>$h$, 81, '2026-11-27') on conflict (id) do update set topic = excluded.topic, title = excluded.title, summary = excluded.summary, tags = excluded.tags, popular = excluded.popular, html = excluded.html, position = excluded.position, updated_on = excluded.updated_on;
insert into help_articles (id, topic, title, summary, tags, popular, html, position, updated_on) values ($h$close-account$h$, $h$account$h$, $h$Close your account$h$, $h$Remove your profile, with 30 days to change your mind.$h$, $h$delete close remove account$h$, false, $h$<ol class="steps"><li>Go to <b>Me</b>, then <b>Privacy and account</b>.</li><li>Select <b>Close or pause</b>, then follow the steps under <b>Close my account</b>. To take a break instead, turn on <b>Pause my profile</b>.</li></ol><p>If you have a paid plan, cancel it first. See <a href="#/a/upgrade">Upgrade, change or cancel your plan</a>. Closing your account removes your profile and your posts. Business pages you own should be handed to another team member first.</p><h3>Changed your mind?</h3><p>You have <b>30 days</b> to restore your account. Use the <b>Restore my account</b> link in the email we send you, or just log in again. After 30 days your information is permanently deleted and we email you to confirm.</p><div class="call note"><b>Good to know</b><span>We keep billing records for 6 years, because Canadian tax rules require it.</span></div>$h$, 82, '2026-11-27') on conflict (id) do update set topic = excluded.topic, title = excluded.title, summary = excluded.summary, tags = excluded.tags, popular = excluded.popular, html = excluded.html, position = excluded.position, updated_on = excluded.updated_on;
insert into help_articles (id, topic, title, summary, tags, popular, html, position, updated_on) values ($h$contact-support$h$, $h$account$h$, $h$Contact the SME Hub team$h$, $h$Email, phone and office address.$h$, $h$contact support help email phone$h$, true, $h$<div class="tw"><table><thead><tr><th>How</th><th>Details</th></tr></thead><tbody><tr><td>Email (members)</td><td>support@smehub.ca</td></tr><tr><td>Email (CanadianSME)</td><td>info@canadiansme.ca</td></tr><tr><td>Phone</td><td>+1 437 778 4446 · +1 416 655 0205</td></tr><tr><td>Office</td><td>Cmarketing Inc., 6345 Dixie Rd, Unit 202, Mississauga, ON L5T 2E6</td></tr></tbody></table></div><p>You can also use the <b>Contact us</b> form under <b>About</b>.</p>$h$, 83, '2026-11-27') on conflict (id) do update set topic = excluded.topic, title = excluded.title, summary = excluded.summary, tags = excluded.tags, popular = excluded.popular, html = excluded.html, position = excluded.position, updated_on = excluded.updated_on;
